def esc(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


def num(v):
    return f'><v>{v!r}</v></c>'


def fnum(v):
    return f'><f>X1+1</f><v>{v!r}</v></c>'


def write_book(path, sheets, strings=()):
    """sheets: {name: {cell: the cell's XML after its reference}}"""
    with zipfile.ZipFile(path, 'w') as z:
        z.writestr('xl/workbook.xml', WB_XML.format(''.join(
            f'<sheet name="{esc(n)}" sheetId="{i + 1}" r:id="rId{i + 1}"/>' for i, n in enumerate(sheets))))
        z.writestr('xl/_rels/workbook.xml.rels', RELS.format(''.join(
            f'<Relationship Id="rId{i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/'
            f'worksheet" Target="worksheets/sheet{i + 1}.xml"/>' for i in range(len(sheets)))))
        if strings:
            z.writestr('xl/sharedStrings.xml', '<?xml version="1.0" encoding="UTF-8"?><sst xmlns="' + MAIN + '">' +
                       ''.join(f'<si><t>{esc(s)}</t></si>' for s in strings) + '</sst>')
        for i, (n, cells) in enumerate(sheets.items()):
            rows = {}
            for ref, xml in cells.items():
                r, c = t_split_ref(ref)
                rows.setdefault(r, []).append((c, ref, xml))
            body = ''.join(f'<row r="{r}">' + ''.join(f'<c r="{ref}"{x}' for _, ref, x in sorted(rows[r])) + '</row>'
                           for r in sorted(rows))
            z.writestr(f'xl/worksheets/sheet{i + 1}.xml', SHEET.format(body))


def tdigest(sheet, pairs):
    """The manifest's canonical lines, written here apart from the tool's own rendering."""
    s = ''
    for ref, v in pairs:
        r = ('TRUE' if v else 'FALSE') if isinstance(v, bool) else (repr(v) if isinstance(v, float) else str(v))
        s += sheet + '!' + ref + '\t' + r + '\n'
    return hashlib.sha256(s.encode('utf-8')).hexdigest()


def text_of(path):
    with open(path, encoding='utf-8') as f:
        return f.read()


def sha(path):
    with open(path, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()


def value(i):
    return 0.0123 + 0.000137 * i + (i * 7919 % 1009) * 1.0e-11


def t_split_ref(ref):
    m = re.fullmatch(r'([A-Z]+)([0-9]+)', ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + ord(ch) - 64
    return int(m.group(2)), col


def t_bounds(rng):
    a, _, b = rng.partition(':')
    (r0, c0), (r1, c1) = t_split_ref(a), t_split_ref(b or a)
    return r0, c0, r1, c1


def t_sig3(d):
    """Three significant digits, half to even, from the exact rational — the test's own, apart from the tool's."""
    d = Fraction(d)
    if d == 0:
        return '0.00e+00'
    e = 0
    while d >= Fraction(10) ** (e + 1):
        e += 1
    while d < Fraction(10) ** e:
        e -= 1
    n = round(d / Fraction(10) ** (e - 2))
    if n == 1000:
        n, e = 100, e + 1
    s = str(n)
    return f'{s[0]}.{s[1:]}e{e:+03d}'


def t_edge(official, band, up):
    """The last double inside the band on one side of the official value — above it, or below it —, found by the
    test's own exact model, never by the judge under test; each search bounded."""
    lim, o = Fraction(band[1]), Fraction(official)
    inside = (lambda v: abs(Fraction(v) - o) <= lim) if band[0] == '<=' else (lambda v: abs(Fraction(v) - o) < lim)
    out, back = (math.inf, -math.inf) if up else (-math.inf, math.inf)
    v = float(o + (lim if up else -lim))
    for _ in range(64):
        if not inside(v):
            break
        v = math.nextafter(v, out)
    else:
        raise AssertionError(f'no double outside {band} found {"above" if up else "below"} {official!r}')
    for _ in range(64):
        v = math.nextafter(v, back)
        if inside(v):
            return v
    raise AssertionError(f'no double inside {band} found near {official!r}')


