UNREAD = object()


class Fault(Exception):
    """An ordinary exception whose message raises when it is rendered."""

    def __str__(self):
        raise RuntimeError('injected: the message cannot be rendered')


class FaultOS(OSError):
    """An OSError whose message raises when it is rendered."""

    def __str__(self):
        raise RuntimeError('injected: the message cannot be rendered')


class Unnamed(type):
    """A metaclass whose classes' own name cannot be read."""

    @property
    def __name__(cls):
        raise RuntimeError('injected: the class name cannot be read')


class Nameless(Exception, metaclass=Unnamed):
    """An exception whose class's name and whose message both raise when they are read."""

    def __str__(self):
        raise RuntimeError('injected: the message cannot be rendered')


class Fixture:
    """Three synthetic workbooks laid out as the declared ranges are — by EXPECTED, not by the tool's ROWS —, and a
    manifest of their digests: each output's value, cell and band known to the test; where boolean names a workbook
    and an output cell, that cell a boolean, TRUE, its range's digest that of the boolean; where official names a
    workbook, an output cell, its XML and the value the tool reads from it, that cell so, its range's digest that of
    the value — or the cell left out of its range's row where the value is UNREAD, as the reader takes an empty
    cell —; where boolean_maturity_row names a row, the maturity there a boolean, TRUE, its range's digest that of the
    boolean; where maturity names a row, its XML and the value the tool reads from it, the maturity there in each range
    of maturities so, its range's digest that of the value, or the cell left out of the row where the value is UNREAD;
    where drop names a workbook and a declared cell, that cell left out of its workbook and of its range's row. edit
    changes one member of a workbook by exact replacements, each found once, and makes its pin again."""

    def __init__(self, folder, maturities=None, maturity_formula_row=None, change=None, boolean=None, official=None,
                 boolean_maturity_row=None, maturity=None, drop=None):
        self.folder = folder
        mats = maturities or list(range(1, 151))
        self.truth, self.cell, self.band, rows, k = {}, {}, {}, [], 0
        books = {'E1': {IDE_: {}, CSS_: {}, VAT_: {}}, 'E2': {'RCS': {}}, 'E3': {'RCS': {}}}
        mat_ranges = {}
        for case, wb, sheet, rng, items in EXPECTED:
            target = books[wb][sheet]
            cells = []
            if isinstance(items, tuple):
                _, key, band, mrng, n = items
                r0, c0, r1, c1 = t_bounds(rng)
                col = rng.split(':')[0].rstrip('0123456789')
                m0 = t_bounds(mrng)[0]
                mcol = mrng.split(':')[0].rstrip('0123456789')
                if mrng not in mat_ranges:
                    mcells = []
                    for j, m in enumerate(mats):
                        ref = f'{mcol}{m0 + j}'
                        if maturity_formula_row == m0 + j:
                            target[ref] = fnum(m)
                        elif boolean_maturity_row == m0 + j:
                            target[ref] = ' t="b"><v>1</v></c>'
                            mcells.append((ref, True))
                        elif maturity is not None and maturity[0] == m0 + j:
                            target[ref] = maturity[1]
                            if maturity[2] is not UNREAD:
                                mcells.append((ref, maturity[2]))
                        else:
                            target[ref] = num(m)
                            mcells.append((ref, m))
                    mat_ranges[mrng] = mcells
                    rows.append((case, 'input', wb, sheet, mrng, 'const', mcells))
                for j in range(r1 - r0 + 1):
                    ref, v = f'{col}{r0 + j}', value(k)
                    k += 1
                    if drop == (wb, ref):
                        continue
                    if change == ref:
                        v = math.nextafter(v, 1.0)
                    target[ref] = fnum(v)
                    cells.append((ref, v))
                    self.truth[(case, key, mats[j])] = v
                    self.cell[(case, key, mats[j])] = f"'{sheet}'!{ref}"
                    self.band[(case, key, mats[j])] = band
            else:
                for cell, key, band in items:
                    v = value(k)
                    k += 1
                    if drop == (wb, cell):
                        continue
                    if boolean == (wb, cell):
                        v = True
                        target[cell] = ' t="b"><f>X1+1</f><v>1</v></c>'
                    elif official is not None and official[:2] == (wb, cell):
                        target[cell], v = official[2], official[3]
                    else:
                        target[cell] = fnum(v)
                    if v is not UNREAD:
                        cells.append((cell, v))
                    self.truth[(case, key, None)] = v
                    self.cell[(case, key, None)] = f"'{sheet}'!{cell}"
                    self.band[(case, key, None)] = band
            rows.append((case, 'output', wb, sheet, rng, 'all', sorted(cells, key=lambda p: t_split_ref(p[0]))))
        books['E1'][IDE_]['A1'] = ' t="s"><v>0</v></c>'
        write_book(os.path.join(folder, 'E1.xlsm'), books['E1'], strings=['a label'])
        write_book(os.path.join(folder, 'E2.xlsm'), books['E2'])
        write_book(os.path.join(folder, 'E3.xlsm'), books['E3'])
        lines = ['# synthetic manifest', '', 'Roles: prose the parser leaves alone', '']
        for case, role, wb, sheet, rng, sel, cells in rows:
            lines.append(f"{case} · {role} · {wb} · '{sheet}'!{rng} · {sel} · {len(cells)} · {tdigest(sheet, cells)} · a label")
        lines.append(f"A1 · input · E1 · '{C.IDE}'!H10:H12 · const · 3 · {'0' * 64} · a row the tool does not read")
        self.manifest = os.path.join(folder, 'MANIFEST.md')
        with open(self.manifest, 'w', encoding='utf-8') as f:
            f.write('\n'.join(lines) + '\n')
        self.pins = {w: sha(os.path.join(folder, w + '.xlsm')) for w in ('E1', 'E2', 'E3')}
        self.msha = sha(self.manifest)

    def oracle(self):
        return C.read_oracle(self.folder, self.manifest, self.pins, self.msha)

    def outputs(self):
        out = {}
        for (case, key, m), v in self.truth.items():
            obj = out.setdefault(case, {})
            if m is None:
                obj[key] = v
            else:
                obj.setdefault(key, {})[str(m)] = v
        return {case: out[case] for case in C.CASES}

    def edit(self, wb, member, *pairs):
        """One member of a workbook changed by exact replacements, each found once; the workbook written again, its
        other members as they were, and its pin made again."""
        path = os.path.join(self.folder, wb + '.xlsm')
        with zipfile.ZipFile(path) as z:
            members = [(i.filename, z.read(i.filename)) for i in z.infolist()]
        if member not in [n for n, _ in members]:
            raise AssertionError(f'{wb}: no member {member}')
        with zipfile.ZipFile(path, 'w') as z:
            for name, data in members:
                if name == member:
                    text = data.decode('utf-8')
                    for old, new in pairs:
                        if text.count(old) != 1:
                            raise AssertionError(f'{wb} {member}: {old!r} found {text.count(old)} times, not once')
                        text = text.replace(old, new)
                    data = text.encode('utf-8')
                z.writestr(name, data)
        self.pins[wb] = sha(path)


def quiet(fn, *a, **kw):
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        r = fn(*a, **kw)
    return r, buf.getvalue()


class Lines(io.StringIO):
    """A stdout that sends SIGINT as its at-th write is made, and fails its fail-th with a broken pipe."""

    def __init__(self, at=None, fail=None):
        super().__init__()
        self.at, self.fail, self.n = at, fail, 0

    def write(self, s):
        self.n += 1
        if self.n == self.fail:
            raise BrokenPipeError(errno.EPIPE, os.strerror(errno.EPIPE))
        r = super().write(s)
        if self.n == self.at:
            signal.raise_signal(signal.SIGINT)
        return r


class Takes(io.StringIO):
    """A stream with no descriptor of its own — a stdout, or a stderr — whose writes take what how says — whole; one
    character; none; or one character and a count that is not one of what it was given: None, True, -1, more than
    given —, sending SIGINT as its at-th write is made; a writer that went on past 100,000 writes meets an injected
    failure."""

    def __init__(self, how='whole', at=None):
        super().__init__()
        self.how, self.at, self.n = how, at, 0

    def write(self, s):
        self.n += 1
        if self.n > 100000:
            raise OSError('injected: the writer went on after 100000 writes')
        if self.n == self.at:
            signal.raise_signal(signal.SIGINT)
        if self.how == 'whole':
            return super().write(s)
        if self.how == 'zero':
            return 0
        took = super().write(s[:1])
        return {'one': took, 'none': None, 'true': True, 'minus': -1, 'more': len(s) + 1}[self.how]


