def probe():
    """The suite's environment with the variables Python 3.14's colour probe reads before the stream cleared —
    PYTHON_COLORS, NO_COLOR, FORCE_COLOR and TERM: _colorize.can_colorize, read at the v3.14.6 tag, answers from any of
    them before it reaches the stream's fileno —, so that a process given it probes its stdout whatever the suite
    inherits; argparse makes that probe as each parser and its formatter are made."""
    return {k: v for k, v in os.environ.items() if k not in ('PYTHON_COLORS', 'NO_COLOR', 'FORCE_COLOR', 'TERM')}


def read_tsv(path):
    with open(path, encoding='utf-8') as f:
        lines = f.read().split('\n')
    head = [l for l in lines if l.startswith('# ')]
    body = [l.split('\t') for l in lines if l and not l.startswith('# ')]
    return head, body[0], body[1:]


class Temp(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix='rt01-compare-')
        self.addCleanup(shutil.rmtree, self.tmp)

    def path(self, *p):
        return os.path.join(self.tmp, *p)

    def dump(self, name, obj=None, text=None):
        p = self.path(name)
        with open(p, 'w' if text is None or isinstance(text, str) else 'wb') as f:
            f.write(json.dumps(obj, indent=1) if text is None else text)
        return p


class TestOracle(Temp):
    def test_reads_and_holds_every_range(self):
        fx = Fixture(self.tmp)
        oracle, held = fx.oracle()
        self.assertEqual(len(oracle), 535)
        self.assertEqual([h[3] for h in held].count('output'), 14)
        self.assertEqual([h[3] for h in held].count('input'), 3)
        for k, (cell, band, v) in oracle.items():
            self.assertEqual(v, fx.truth[k])
        self.assertEqual(list(oracle)[:3], [('A1', 'zero_rates_cc', 1), ('A1', 'zero_rates_cc', 2), ('A1', 'zero_rates_cc', 3)])
        self.assertEqual(list(oracle)[-1], ('C1', 'rcs', None))

    def test_pin_stops(self):
        fx = Fixture(self.tmp)
        pins = dict(fx.pins, E2='0' * 64)
        with self.assertRaisesRegex(C.Stop, 'E2.xlsm: sha256 .* is not its pin'):
            C.read_oracle(self.tmp, fx.manifest, pins, fx.msha)

    def test_manifest_sha_stops(self):
        fx = Fixture(self.tmp)
        with self.assertRaisesRegex(C.Stop, "is not the frozen manifest's"):
            C.read_oracle(self.tmp, fx.manifest, fx.pins, '1' * 64)

    def test_a_changed_cell_differs_from_its_digest(self):
        fx = Fixture(self.tmp)
        manifest = text_of(fx.manifest)
        os.makedirs(self.path('b'))
        fy = Fixture(self.path('b'), change='L30')
        with open(fy.manifest, 'w', encoding='utf-8') as f:
            f.write(manifest)
        with self.assertRaisesRegex(C.Stop, r"'Input Data & Extrapolation'!L25:L174: .* the range differs from its digest"):
            C.read_oracle(fy.folder, fy.manifest, fy.pins, sha(fy.manifest))

    def test_a_formula_among_the_maturities_is_left_out_and_stops_the_curve(self):
        fx = Fixture(self.tmp, maturity_formula_row=30)
        with self.assertRaisesRegex(C.Stop, r"'Input Data & Extrapolation'!K30: its row carries no integer maturity"):
            fx.oracle()

    def test_maturities_out_of_order_stop(self):
        mats = list(range(1, 151))
        mats[0], mats[1] = 2, 1
        fx = Fixture(self.tmp, maturities=mats)
        with self.assertRaisesRegex(C.Stop, 'its maturities are not 1 to 50 in order'):
            fx.oracle()

    def test_a_missing_row_in_the_manifest_stops(self):
        fx = Fixture(self.tmp)
        text = text_of(fx.manifest).replace("'RCS'!K11:K19", "'RCS'!K11:K18")
        with open(fx.manifest, 'w', encoding='utf-8') as f:
            f.write(text)
        with self.assertRaisesRegex(C.Stop, r"E2 'RCS'!K11:K19: 0 rows in the manifest, not one"):
            C.read_oracle(self.tmp, fx.manifest, fx.pins, sha(fx.manifest))

    def test_a_manifest_row_of_another_role_selection_or_count_stops_its_digest_right(self):
        fx = Fixture(self.tmp)
        text = text_of(fx.manifest)
        line = [l for l in text.split('\n') if "'RCS'!K11:K19" in l][0]
        for old, new, why in ((' · output · ', ' · input · ', "the manifest's row is input/all, not output/all"),
                              (' · all · ', ' · const · ', "the manifest's row is output/const, not output/all"),
                              (' · 9 · ', ' · 999 · ', "9 cells, sha256 .* — the manifest's row 999 cells")):
            with open(fx.manifest, 'w', encoding='utf-8') as f:
                f.write(text.replace(line, line.replace(old, new, 1)))
            with self.assertRaisesRegex(C.Stop, "E2 'RCS'!K11:K19: " + why):
                C.read_oracle(self.tmp, fx.manifest, fx.pins, sha(fx.manifest))

    def test_cached_values_and_their_rendering(self):
        fx = Fixture(self.tmp)
        b = C.Book(os.path.join(self.tmp, 'E1.xlsm'))
        self.assertEqual(b.cached('s', '0', None), 'a label')
        self.assertIs(b.cached('b', '1', None), True)
        self.assertIs(type(b.cached('n', '5', None)), int)
        self.assertIs(type(b.cached('n', '5.0', None)), float)
        self.assertEqual(b.cached('n', '2E-3', None), 0.002)
        self.assertEqual(b.cached('str', 'x', None), 'x')
        self.assertEqual(b.cached('e', '#N/A', None), '#N/A')
        self.assertIsNone(b.cached('n', None, None))
        with self.assertRaises(C.Stop):
            b.cached('d', '2026-01-01', None)
        self.assertEqual([C.render(v) for v in (True, False, 5, 0.1, 'a\tb\\c\nd')],
                         ['TRUE', 'FALSE', '5', '0.1', 'a\\tb\\\\c\\nd'])
        self.assertEqual(b.cells(C.IDE, 'A1:A1', 'all'), [('A1', 'a label')])

    def test_an_official_negative_zero_keeps_its_sign_through_the_hold_and_the_a1_file(self):
        """A cached negative zero — its text with '.', with 'E' and with 'e' — read as -0.0, its rendering the
        manifest's, '-0.0'; a held range's cell carrying it — A1's llfr, its text '-0.0' and '-0E0' —, the range's
        canonical line the manifest's: the hold passing, the oracle's value -0.0 and a1's file carrying -0.0 where it
        is the official (the sweep's S0084 on revision 120's bytes: the oracle's reader at a negative zero)."""
        fx = Fixture(self.tmp)
        b = C.Book(os.path.join(self.tmp, 'E1.xlsm'))
        for t in ('-0.0', '-0E0', '-0e0'):
            v = b.cached('n', t, None)
            self.assertEqual((type(v), v, math.copysign(1.0, v), C.render(v)), (float, 0.0, -1.0, '-0.0'), t)
        for t in ('-0.0', '-0E0'):
            d = self.path('zero' + t)
            os.makedirs(d)
            fz = Fixture(d, official=('E1', 'L22', f'><f>X1+1</f><v>{t}</v></c>', -0.0))
            oracle, held = fz.oracle()
            self.assertEqual([h[3] for h in held].count('output'), 14, t)
            v = oracle[('A1', 'llfr', None)][2]
            self.assertEqual((v, math.copysign(1.0, v)), (0.0, -1.0), t)
            out = os.path.join(d, 'a1.json')
            r, log = quiet(C.cmd_a1, d, fz.manifest, out, fz.pins, fz.msha)
            self.assertEqual(r, 0, t)
            a1 = json.loads(text_of(out))
            self.assertEqual((a1['llfr'], math.copysign(1.0, a1['llfr'])), (0.0, -1.0), t)
            self.assertRegex(text_of(out), r'"llfr": -0\.0[,\n]', t)


class TestBands(unittest.TestCase):
    def edge(self, official, band, up):
        return t_edge(official, band, up)

    def test_the_double_nearest_a_band_at_an_official_zero(self):
        for band in (C.CURVE, C.VA4, C.EXACT):
            near = float(Fraction(band[1]))
            self.assertGreater(Fraction(near), Fraction(band[1]))
            self.assertFalse(C.judge(near, 0.0, band)[0])
            self.assertTrue(C.judge(math.nextafter(near, 0.0), 0.0, band)[0])

    def test_the_last_double_inside_passes_and_the_next_fails_on_either_side(self):
        for band in BANDS:
            for official in (0.0123456789012345, -0.0007, 0.0):
                for up in (True, False):
                    v = self.edge(official, band, up)
                    ok, d = C.judge(v, official, band)
                    self.assertTrue(ok)
                    self.assertEqual(d, abs(Fraction(v) - Fraction(official)))
                    self.assertTrue(d <= Fraction(band[1]))
                    self.assertFalse(C.judge(math.nextafter(v, math.inf if up else -math.inf), official, band)[0])

    def test_three_significant_digits_rounded_half_to_even(self):
        for d, s in ((Fraction(0), '0.00e+00'), (Fraction('1.23456'), '1.23e+00'), (Fraction('1.235'), '1.24e+00'),
                     (Fraction('1.225'), '1.22e+00'), (Fraction('9.995'), '1.00e+01'), (Fraction('0.000123449'), '1.23e-04'),
                     (Fraction(1, 3), '3.33e-01'), (Fraction(2) ** -1074, '4.94e-324'), (Fraction(C.MAX_INT), '1.80e+308')):
            self.assertEqual(C.sig3(d), s)
            self.assertEqual(t_sig3(d), s)

    def test_three_significant_digits_half_to_even_under_a_callers_context(self):
        """sig3 called inside a caller's decimal context that rounds up: the same half-to-even display — its rounding
        its own, not the caller's —, and the caller's context left as it was."""
        with decimal.localcontext() as ctx:
            ctx.rounding = decimal.ROUND_UP
            for d, s in ((Fraction('1.23456'), '1.23e+00'), (Fraction('1.225'), '1.22e+00'),
                         (Fraction('1.235'), '1.24e+00'), (Fraction(1, 3), '3.33e-01')):
                self.assertEqual(C.sig3(d), s, d)
            self.assertEqual(decimal.getcontext().rounding, decimal.ROUND_UP)

    def test_three_significant_digits_whatever_the_callers_traps_and_bounds(self):
        """sig3 called inside a caller's decimal context — Inexact trapped, Rounded trapped, every signal trapped, or
        the exponent bounds narrowed to Emax=1 and Emin=-1 —: each display the default context's, nothing raised; the
        caller's context — its precision, rounding, bounds, clamp, capitals, traps and flags — left as it was."""
        cases = (Fraction(1, 3), Fraction(100), Fraction(123456, 10 ** 11), Fraction('1.225'), Fraction('9.995'),
                 Fraction(2) ** -1074, Fraction(C.MAX_INT))
        plain = ['3.33e-01', '1.00e+02', '1.23e-06', '1.22e+00', '1.00e+01', '4.94e-324', '1.80e+308']
        self.assertEqual([C.sig3(d) for d in cases], plain)
        for what in ('Inexact', 'Rounded', 'every', 'bounds'):
            with decimal.localcontext() as ctx:
                if what == 'every':
                    for s in list(ctx.traps):
                        ctx.traps[s] = True
                elif what == 'bounds':
                    ctx.Emax, ctx.Emin = 1, -1
                else:
                    ctx.traps[getattr(decimal, what)] = True
                was = (ctx.prec, ctx.rounding, ctx.Emax, ctx.Emin, ctx.clamp, ctx.capitals, dict(ctx.traps),
                       dict(ctx.flags))
                self.assertEqual([C.sig3(d) for d in cases], plain, what)
                now = decimal.getcontext()
                self.assertEqual((now.prec, now.rounding, now.Emax, now.Emin, now.clamp, now.capitals, dict(now.traps),
                                  dict(now.flags)), was, what)

    def test_strict_and_inclusive_at_an_exact_band(self):
        self.assertTrue(C.within('<=', Fraction('0.0009765625'), Fraction(1, 1024)))
        self.assertFalse(C.within('<', Fraction('0.0009765625'), Fraction(1, 1024)))

    def test_the_difference_is_exact(self):
        ok, d = C.judge(0.1 + 0.2, 0.3, C.EXACT)
        self.assertEqual(d, Fraction(0.1 + 0.2) - Fraction(0.3))
        self.assertTrue(ok)
        self.assertEqual(C.judge(7, 7.0, C.EXACT), (True, Fraction(0)))


class TestBuilds(Temp):
    def planted(self, fx):
        o = fx.outputs()
        t = fx.truth
        o['A1']['basic_rfr']['17'] = t[('A1', 'basic_rfr', 17)] + 2.0e-5
        o['A1']['llfr'] = None
        del o['A2']['cssr']
        o['A2']['curve']['1'] = '@@BIG@@'
        o['A3']['curve']['150'] = '@@NAN@@'
        o['A3']['total_va'] = t[('A3', 'total_va', None)] + 0.49e-4
        o['A3']['omega_co'] = t[('A3', 'omega_co', None)] + 1.1e-9
        o['A1']['extra'] = 1
        o['Z9'] = 1
        o['A2']['curve']['151'] = 0.5
        o['B1']['s'] = '0.01'
        o['B2']['rcs'] = True
        o['C1']['@@DUP@@'] = 0
        text = json.dumps(o, indent=1)
        text = text.replace('"@@BIG@@"', '1e400').replace('"@@NAN@@"', 'NaN').replace('"@@DUP@@": 0', '"rc": 0.5')
        return self.dump('x.json', text=text)

    def table(self, fx, builds, isolated=(), out='t'):
        r, log = quiet(C.cmd_table, self.tmp, fx.manifest, self.path(out), builds, list(isolated), fx.pins, fx.msha)
        self.assertEqual(r, 0)
        return log, {n: read_tsv(self.path(out, n)) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')}

    def test_a_build_equal_to_the_oracle_passes_every_output(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        self.assertEqual(C.form(*C.load(ok)), ([], 535, 0))
        log, t = self.table(fx, [('build-ok', ok)])
        head, cols, rows = t['table.tsv']
        self.assertEqual(len(rows), 535)
        self.assertTrue(all(r[9] == 'PASS' for r in rows))
        self.assertEqual([r[6] for r in t['cases.tsv'][2]], ['PASS'] * 6)
        self.assertEqual(t['divergences.tsv'][2], [])
        self.assertIn(f'# tool: compare.py sha256 {sha(os.path.join(HERE, "compare.py"))}', head)
        self.assertIn('# command: compare.py table <workbooks> <manifest> <out> --build build-ok <build-ok returned> — '
                      'every file and folder shown by its role, the files named by their sha256 below', head)
        self.assertTrue(any(h.startswith('# Source: EIOPA') for h in head))
        self.assertEqual(cols, ['build', 'kind', 'case', 'key', 'maturity', 'cell', 'band', 'value', 'difference',
                                'result', 'why'])

    def test_each_failure_the_brief_names_fails_its_output_and_nothing_else(self):
        fx = Fixture(self.tmp)
        x = self.planted(fx)
        log, t = self.table(fx, [('build-x', x)])
        fails = {(r[2], r[3], r[4]): r[10] for r in t['table.tsv'][2] if r[9] == 'FAIL'}
        self.assertEqual(fails, {
            ('A1', 'basic_rfr', '17'): 'outside its band', ('A1', 'llfr', '-'): 'null', ('A2', 'cssr', '-'): 'missing',
            ('A2', 'curve', '1'): 'non-numeric: 1e400, past the double range',
            ('A3', 'curve', '150'): 'non-numeric: NaN, not a JSON number', ('A3', 'omega_co', '-'): 'outside its band',
            ('B1', 's', '-'): 'non-numeric: a JSON string', ('B2', 'rcs', '-'): 'non-numeric: a JSON boolean',
            ('C1', 'rc', '-'): 'given twice'})
        div = t['divergences.tsv'][2]
        self.assertEqual(len(div), 9)
        self.assertIn('build-x/returned/A1.basic_rfr[17]', [d[0] for d in div])
        self.assertIn('build-x/returned/A1.llfr', [d[0] for d in div])
        self.assertEqual([r[6] for r in t['cases.tsv'][2]], ['FAIL'] * 6)
        dev, n, nulls = C.form(*C.load(x))
        self.assertEqual(sorted(dev), sorted([
            "keys beyond the brief's six: ['Z9']", "A1: keys beyond the brief's: ['extra']",
            "A2.curve: keys beyond maturities 1 to 150: ['151']", 'A2.cssr missing',
            'A3.curve.150: non-numeric: NaN, not a JSON number', 'B1.s: non-numeric: a JSON string',
            'B2.rcs: non-numeric: a JSON boolean', 'C1.rc: given twice',
            'A2.curve.1: non-numeric: 1e400, past the double range']))
        self.assertEqual((n, nulls), (535 - 7, 1))
        self.assertIn('build-x returned · form deviation: A2.cssr missing', log)
        self.assertIn(f'# build-x returned: sha256 {sha(x)} · form: 9 deviation(s) · numbers 528 of 535 · null, not '
                      'computed: 1', t['table.tsv'][0])

    def test_a_failed_rows_band_is_the_band_the_judged_row_of_its_output_carries(self):
        """Beside a build equal to the oracle, a build whose outputs fail before they are judged — the brief's
        failures: a missing one, a null, a string, a boolean, one given twice, one past the double range, a NaN — and
        one whose file does not parse, every output failed: each failed row's band column, in table.tsv and in
        divergences.tsv, the band's text the judged row of its output carries — its operator, then its bound (the
        sweep's S0471, S0472 and S0474 on revision 119's bytes)."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        x = self.planted(fx)
        bad = self.dump('bad.json', text='{"A1": ')
        log, t = self.table(fx, [('build-ok', ok), ('build-x', x), ('build-bad', bad)])
        rows = t['table.tsv'][2]
        judged = {(r[2], r[3], r[4]): r[6] for r in rows if r[0] == 'build-ok'}
        self.assertEqual(len(judged), 535)
        self.assertEqual({b.split(' ')[0] for b in judged.values()}, {'<=', '<'})
        self.assertTrue(all(len(b.split(' ')) == 2 and b.split(' ')[1] not in ('<=', '<') for b in judged.values()))
        failed = [r for r in rows if r[0] != 'build-ok' and r[7] == '-']
        self.assertEqual(sorted((r[2], r[3], r[4], r[10]) for r in failed if r[0] == 'build-x'), [
            ('A1', 'llfr', '-', 'null'), ('A2', 'cssr', '-', 'missing'),
            ('A2', 'curve', '1', 'non-numeric: 1e400, past the double range'),
            ('A3', 'curve', '150', 'non-numeric: NaN, not a JSON number'),
            ('B1', 's', '-', 'non-numeric: a JSON string'), ('B2', 'rcs', '-', 'non-numeric: a JSON boolean'),
            ('C1', 'rc', '-', 'given twice')])
        self.assertEqual([r[10] for r in failed if r[0] == 'build-bad'], ['the file does not parse'] * 535)
        for r in failed:
            self.assertEqual(r[6], judged[(r[2], r[3], r[4])], r)
        div = [d for d in t['divergences.tsv'][2] if d[1] != 'build-ok' and d[8] == '-']
        want = sorted((r[0], r[2], r[3], r[4]) for r in failed)
        self.assertEqual(sorted((d[1], d[3], d[4], d[5]) for d in div), want)
        for d in div:
            self.assertEqual(d[7], judged[(d[3], d[4], d[5])], d)

    def test_isolated_outputs_are_their_own_rows(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        iso = fx.outputs()
        iso['A2']['notional_va'] += 0.6e-4
        del iso['B1']
        isop = self.dump('iso.json', iso)
        self.assertEqual(C.form(*C.load(isop), isolated=True), ([], 307, 0))
        log, t = self.table(fx, [('build-ok', ok)], [('build-ok', isop)])
        rows = t['table.tsv'][2]
        self.assertEqual(len(rows), 535 + 307)
        self.assertEqual({r[2] for r in rows if r[1] == 'isolated'}, {'A2', 'A3'})
        self.assertEqual([(c[1], c[2], c[6]) for c in t['cases.tsv'][2] if c[1] == 'isolated'],
                         [('isolated', 'A2', 'FAIL'), ('isolated', 'A3', 'PASS')])
        self.assertEqual([d[0] for d in t['divergences.tsv'][2]], ['build-ok/isolated/A2.notional_va'])

    def test_a_file_that_does_not_parse_fails_every_output(self):
        fx = Fixture(self.tmp)
        bad = self.dump('bad.json', text='{"A1": ')
        arr = self.dump('arr.json', text='[1, 2]')
        log, t = self.table(fx, [('bad', bad), ('arr', arr)])
        rows = t['table.tsv'][2]
        self.assertEqual({r[10] for r in rows if r[0] == 'bad'}, {'the file does not parse'})
        self.assertEqual({r[10] for r in rows if r[0] == 'arr'}, {'the file is not a JSON object'})
        self.assertEqual(len(t['divergences.tsv'][2]), 1070)

    def test_a_byte_order_mark_is_a_deviation_and_its_values_count(self):
        fx = Fixture(self.tmp)
        p = self.dump('bom.json', text=b'\xef\xbb\xbf' + json.dumps(fx.outputs()).encode())
        self.assertEqual(C.form(*C.load(p)), (['a UTF-8 byte-order mark before the JSON'], 535, 0))
        log, t = self.table(fx, [('bom', p)])
        self.assertTrue(all(r[9] == 'PASS' for r in t['table.tsv'][2]))

    def test_same_compares_every_declared_output_exactly(self):
        fx = Fixture(self.tmp)
        a = self.dump('a.json', fx.outputs())
        o = fx.outputs()
        o['A1']['zero_rates_cc']['3'] = math.nextafter(o['A1']['zero_rates_cc']['3'], 1.0)
        b = self.dump('b.json', o)
        c = self.dump('c.json', text=json.dumps(fx.outputs(), indent=4))
        r, log = quiet(C.cmd_same, a, b)
        self.assertEqual(r, 1)
        self.assertIn('declared outputs: 535 · equal 534 · differing 1', log)
        self.assertIn('differs: A1.zero_rates_cc[3]', log)
        r, log = quiet(C.cmd_same, a, c)
        self.assertEqual(r, 0)
        self.assertIn("the files' bytes equal: False", log)

    def test_the_a1_file_is_the_bare_a1_object_value_for_value(self):
        fx = Fixture(self.tmp)
        out = self.path('a1.json')
        r, log = quiet(C.cmd_a1, self.tmp, fx.manifest, out, fx.pins, fx.msha)
        self.assertEqual(r, 0)
        a1 = json.loads(text_of(out))
        self.assertEqual(sorted(a1), ['basic_rfr', 'llfr', 'zero_rates_cc'])
        self.assertEqual([list(a1['zero_rates_cc']), list(a1['basic_rfr'])],
                         [[str(m) for m in range(1, 51)], [str(m) for m in range(1, 151)]])
        self.assertEqual(a1['llfr'], fx.truth[('A1', 'llfr', None)])
        for m in range(1, 51):
            self.assertEqual(a1['zero_rates_cc'][str(m)], fx.truth[('A1', 'zero_rates_cc', m)])
        for m in range(1, 151):
            self.assertEqual(a1['basic_rfr'][str(m)], fx.truth[('A1', 'basic_rfr', m)])
        with self.assertRaisesRegex(C.Stop, 'exists'):
            quiet(C.cmd_a1, self.tmp, fx.manifest, out, fx.pins, fx.msha)

    def test_the_table_writes_a_new_folder_only(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        os.makedirs(self.path('t'))
        with self.assertRaisesRegex(C.Stop, 'exists'):
            C.cmd_table(self.tmp, fx.manifest, self.path('t'), [('b', ok)], [], fx.pins, fx.msha)
        with self.assertRaisesRegex(C.Stop, 'each build named once'):
            C.cmd_table(self.tmp, fx.manifest, self.path('u'), [('b', ok), ('b', ok)], [], fx.pins, fx.msha)
        with self.assertRaisesRegex(C.Stop, 'each build named once'):
            C.cmd_table(self.tmp, fx.manifest, self.path('u'), [('b', ok)], [('c', ok)], fx.pins, fx.msha)
        with self.assertRaises(C.Stop):
            C.cmd_table(self.tmp, fx.manifest, self.path('no-parent', 'u'), [('b', ok)], [], fx.pins, fx.msha)
        self.assertFalse(os.path.exists(self.path('u')))
        self.assertFalse(os.path.exists(self.path('no-parent')))

    def test_every_field_of_every_row_and_the_two_files_made_from_them(self):
        fx = Fixture(self.tmp)
        o, given = fx.outputs(), {}
        for i, k in enumerate(fx.truth):
            v = fx.truth[k] + (i % 7 - 3) * 1.0e-6 * (1 + i % 5)
            given[k] = v
            if k[2] is None:
                o[k[0]][k[1]] = v
            else:
                o[k[0]][k[1]][str(k[2])] = v
        p = self.dump('shifted.json', o)
        log, t = self.table(fx, [('b', p)])
        want = []
        for k, v in given.items():
            op, lim = fx.band[k]
            d = abs(Fraction(v) - Fraction(fx.truth[k]))
            ok = d <= Fraction(lim) if op == '<=' else d < Fraction(lim)
            want.append(['b', 'returned', k[0], k[1], '-' if k[2] is None else str(k[2]), fx.cell[k], f'{op} {lim}',
                         repr(v), t_sig3(d), 'PASS' if ok else 'FAIL', '' if ok else 'outside its band'])
        self.assertEqual(t['table.tsv'][2], want)
        self.assertTrue(any(r[9] == 'FAIL' and Fraction(r[7]) < Fraction(fx.truth[(r[2], r[3], None if r[4] == '-' else
                                                                                    int(r[4]))]) for r in want))
        cases = []
        for case in ('A1', 'A2', 'A3', 'B1', 'B2', 'C1'):
            sel = [r for r in want if r[2] == case]
            failed = sum(r[9] == 'FAIL' for r in sel)
            cases.append(['b', 'returned', case, str(len(sel)), str(len(sel) - failed), str(failed),
                          'FAIL' if failed else 'PASS'])
        self.assertEqual(t['cases.tsv'][1], ['build', 'kind', 'case', 'outputs', 'passed', 'failed', 'result'])
        self.assertEqual(t['cases.tsv'][2], cases)
        div = [[f'b/returned/{r[2]}.{r[3]}' + ('' if r[4] == '-' else f'[{r[4]}]'), r[0], r[1], r[2], r[3], r[4], r[5],
                r[6], r[7], r[8], r[10]] for r in want if r[9] == 'FAIL']
        self.assertEqual(t['divergences.tsv'][1], ['id', 'build', 'kind', 'case', 'key', 'maturity', 'cell', 'band',
                                                   'value', 'difference', 'why'])
        self.assertEqual(t['divergences.tsv'][2], div)

    def test_an_integer_past_the_double_range_fails_its_output_and_the_table_completes(self):
        fx = Fixture(self.tmp)
        base = json.dumps(fx.outputs())
        tokens = ['1' + '0' * 400, '9' * 5000, str(C.MAX_INT + 1), '-' + '1' + '0' * 400, str(-C.MAX_INT - 1)]
        admitted = [C.MAX_INT, -C.MAX_INT]
        builds = []
        for i, tok in enumerate(tokens + [str(v) for v in admitted]):
            o = json.loads(base)
            o['A1']['llfr'] = '@@INT@@'
            p = self.dump(f'int{i}.json', text=json.dumps(o).replace('"@@INT@@"', tok))
            builds.append((f'int{i}', p))
            dev, n, nulls = C.form(*C.load(p))
            if i < len(tokens):
                self.assertEqual((n, nulls, len(dev)), (534, 0, 1))
                self.assertTrue(dev[0].startswith('A1.llfr: non-numeric: ') and dev[0].endswith('past the double range'))
            else:
                self.assertEqual((dev, n, nulls), ([], 535, 0))
        log, t = self.table(fx, builds)
        rows = {r[0]: r for r in t['table.tsv'][2] if (r[2], r[3]) == ('A1', 'llfr')}
        for i in range(len(tokens)):
            self.assertEqual(rows[f'int{i}'][7:10], ['-', '-', 'FAIL'])
            self.assertTrue(rows[f'int{i}'][10].endswith('past the double range'))
        for i, v in enumerate(admitted, len(tokens)):
            d = abs(Fraction(v) - Fraction(fx.truth[('A1', 'llfr', None)]))
            self.assertEqual(rows[f'int{i}'][7:10], [str(v), t_sig3(d), 'FAIL'])
        self.assertEqual(len(t['table.tsv'][2]), 535 * (len(tokens) + len(admitted)))

