    def test_each_command_says_and_writes_the_same_whatever_its_callers_decimal_context(self):
        """Each command — form, a1, table and same — run by main inside a caller's decimal context — Inexact trapped,
        Rounded trapped, every signal trapped, or the exponent bounds narrowed to Emax=1 and Emin=-1 —, on a synthetic
        build whose A1 llfr lies 1e-8 from the oracle's, its difference shown 1.00e-08: the exit, the lines said on
        stdout and on stderr — the output's path read as its role — and each file written, byte for byte, the default
        context's; the caller's context — precision, rounding, bounds, clamp, capitals, traps and flags — left as it
        was."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        o['A1']['llfr'] = fx.truth[('A1', 'llfr', None)] + 1e-8
        b = self.dump('b.json', o)
        ok = self.dump('ok.json', fx.outputs())

        def state(c):
            return c.prec, c.rounding, c.Emax, c.Emin, c.clamp, c.capitals, dict(c.traps), dict(c.flags)

        def run(what, kind):
            out = self.path(f'ctx-{what}-{kind}' + ('.json' if kind == 'a1' else ''))
            argv = {'form': ['form', b], 'same': ['same', b, ok]}.get(kind) or self.argv(fx, kind, out, b)
            so, se = io.StringIO(), io.StringIO()
            with contextlib.ExitStack() as st:
                st.enter_context(mock.patch.object(C, 'PINS', fx.pins))
                st.enter_context(mock.patch.object(C, 'MANIFEST_SHA256', fx.msha))
                st.enter_context(contextlib.redirect_stdout(so))
                st.enter_context(contextlib.redirect_stderr(se))
                ctx = st.enter_context(decimal.localcontext())
                if what == 'every':
                    for s in list(ctx.traps):
                        ctx.traps[s] = True
                elif what == 'bounds':
                    ctx.Emax, ctx.Emin = 1, -1
                elif what != 'default':
                    ctx.traps[getattr(decimal, what)] = True
                was = state(ctx)
                got = C.main(argv)
                kept = state(decimal.getcontext()) == was
            files = []
            for n in {'a1': [''], 'table': ['table.tsv', 'cases.tsv', 'divergences.tsv']}.get(kind, []):
                p = os.path.join(out, n) if n else out
                if not os.path.isfile(p):
                    files.append(None)
                    continue
                with open(p, 'rb') as f:
                    files.append(f.read())
            return got, so.getvalue().replace(out, '<out>'), se.getvalue().replace(out, '<out>'), files, kept

        for kind in ('form', 'a1', 'table', 'same'):
            plain = run('default', kind)
            self.assertEqual((plain[0], plain[2], plain[4]), (1 if kind == 'same' else 0, '', True), kind)
            if kind == 'table':
                self.assertIn(b'\t1.00e-08\tFAIL\toutside its band\n', plain[3][0])
            for what in ('Inexact', 'Rounded', 'every', 'bounds'):
                self.assertEqual(run(what, kind), plain, (what, kind))

