        """table on a build whose cases carry passes and failures both — A1's llfr and A3's omega_co each outside its
        band, the other outputs the oracle's —: each case's line said on stdout — its outputs, its pass and its fail
        counts and its result — its row of cases.tsv, the six lines the file's six rows in their order."""
