    def creating(self, at, act, calls):
        """os.open as the tool calls it, act(path, real os.open, flags, args) run at the at-th file it creates."""
        real = os.open

        def wrapped(path, flags, *a, **kw):
            if flags & os.O_CREAT:
                calls.append(path)
                if len(calls) == at:
                    return act(path, real, flags, a, kw)
            return real(path, flags, *a, **kw)
        return mock.patch.object(C.os, 'open', wrapped)

    def another(self, path, text="another's"):
        with open(path, 'w') as f:
            f.write(text)

