    def test_the_files_go_into_the_folder_the_run_made_never_through_a_link(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        other = self.path('elsewhere')
        os.makedirs(other)
        out, real = self.path('t'), os.mkdir

        def exchanged(path, *a, **kw):
            real(path, *a, **kw)
            os.rename(out, out + '-made')
            os.symlink(other, out)
        with mock.patch.object(C.os, 'mkdir', exchanged):
            with self.assertRaisesRegex(C.Stop, r'\(OSError: the new folder cannot be opened as the folder made — a link or '
                                                r'another in its place \(.*\)\) — left: .*t — not opened as the folder the '
                                                r'run made: not removed$'):
                C.cmd_table(self.tmp, fx.manifest, out, [('b', ok)], [], fx.pins, fx.msha)
        for at, before in ((2, True), (3, False)):
            out, calls = self.path(f'u{at}'), []

            def relink(path, real_open, flags, a, kw, out=out, before=before):
                fd = None if before else real_open(path, flags, *a, **kw)
                os.rename(out, out + '-made')
                os.symlink(other, out)
                return fd if fd is not None else real_open(path, flags, *a, **kw)
            with self.creating(at, relink, calls):
                with self.assertRaisesRegex(C.Stop, r'\(OSError: the folder at its path is no longer the folder the run made '
                                                    r"and wrote into\) — left: .*u\d — another's in its place, not removed"):
                    C.cmd_table(self.tmp, fx.manifest, out, [('b', ok)], [], fx.pins, fx.msha)
            self.assertEqual(os.listdir(out + '-made'), [])
        self.assertEqual(os.listdir(other), [])

