    def test_each_input_is_read_once_its_sha256_that_of_the_bytes_judged(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        first, o = open(ok, 'rb').read(), fx.outputs()
        o['A1']['llfr'] = 1
        second = json.dumps(o).encode()
        os.makedirs(self.path('b'))
        e1, e1_other = self.path('E1.xlsm'), open(Fixture(self.path('b'), change='L30').folder + '/E1.xlsm', 'rb').read()
        real = C.read_bytes

        def replacing(path, after=None):
            data = real(path)
            for p, new in (after or {ok: second, e1: e1_other}).items():
                if path == p:
                    with open(p, 'wb') as f:
                        f.write(new)
            return data
        with mock.patch.object(C, 'read_bytes', replacing):
            log, t = self.table(fx, [('b', ok)])
        self.assertIn(f'# b returned: sha256 {hashlib.sha256(first).hexdigest()} · form: conforming · numbers 535 of 535',
                      t['table.tsv'][0])
        self.assertTrue(all(r[9] == 'PASS' for r in t['table.tsv'][2]))
        for cmd in ('form', 'same'):
            p = self.dump(f'{cmd}.json', text=first.decode())
            with mock.patch.object(C, 'read_bytes', lambda path, p=p: replacing(path, {p: second})):
                r, log = quiet(C.cmd_form, p, False) if cmd == 'form' else quiet(C.cmd_same, p, ok)
            self.assertIn(f'{p} · sha256 {hashlib.sha256(first).hexdigest()}', log)
        reads, bad = [], fx.outputs()
        bad['A1']['llfr'] = []
        bad = json.dumps(bad).encode()

        def counting(path, after):
            reads.append(path)
            return replacing(path, after)
        p = self.dump('form-bad.json', text=bad.decode())
        with mock.patch.object(C, 'read_bytes', lambda path: counting(path, {p: first})):
            r, log = quiet(C.cmd_form, p, False)
        self.assertEqual((r, reads), (1, [p]))
        self.assertIn(f'{p} · sha256 {hashlib.sha256(bad).hexdigest()}', log)
        self.assertIn('deviation: A1.llfr: non-numeric: a JSON array', log)
        self.assertIn('FORM: 1 deviation(s)', log)
        reads.clear()
        p, q = self.dump('same-a.json', text=first.decode()), self.dump('same-b.json', text=first.decode())
        with mock.patch.object(C, 'read_bytes', lambda path: counting(path, {p: second})):
            r, log = quiet(C.cmd_same, p, q)
        self.assertEqual((r, reads), (0, [p, q]))
        self.assertIn(f'{p} · sha256 {hashlib.sha256(first).hexdigest()}', log)
        self.assertIn('declared outputs: 535 · equal 535 · differing 0', log)

