    def test_same_holds_two_integers_a_double_cannot_tell_apart(self):
        fx = Fixture(self.tmp)
        base, files = json.dumps(fx.outputs()), []
        for i, tok in enumerate((str(2 ** 53), str(2 ** 53 + 1))):
            o = json.loads(base)
            o['A1']['llfr'] = '@@INT@@'
            files.append(self.dump(f's{i}.json', text=json.dumps(o).replace('"@@INT@@"', tok)))
        r, log = quiet(C.cmd_same, *files)
        self.assertEqual(r, 1)
        self.assertIn('declared outputs: 535 · equal 534 · differing 1', log)
        self.assertIn(f'differs: A1.llfr: {2 ** 53} · {2 ** 53 + 1}', log)

    def test_same_holds_one_rational_equal_whatever_its_spelling(self):
        """Two builds that differ at one position — A1's llfr — by one rational's spelling alone: the integer 1 and
        1.0; -0.0 and 0.0; the largest finite double written as the integer it is, 309 digits, and as the double:
        same holds every declared output equal, 0 (RP-P25's F1: an equality of the two values' spellings in place of
        the rationals' passed the whole suite)."""
        fx = Fixture(self.tmp)
        base = json.dumps(fx.outputs())
        big = sys.float_info.max
        for i, pair in enumerate((('1', '1.0'), ('-0.0', '0.0'), (str(int(big)), repr(big)))):
            files = []
            for j, tok in enumerate(pair):
                o = json.loads(base)
                o['A1']['llfr'] = '@@NUM@@'
                files.append(self.dump(f'r{i}{j}.json', text=json.dumps(o).replace('"@@NUM@@"', tok)))
            r, log = quiet(C.cmd_same, *files)
            self.assertEqual(r, 0, pair)
            self.assertIn('declared outputs: 535 · equal 535 · differing 0', log, pair)

    def test_same_tells_neighbours_apart_at_the_largest_magnitudes_it_admits(self):
        """Two builds one unit apart — 10**100 and 10**100 + 1, the largest double's integer and the one below it,
        each pair on both signs — at one scalar alone, A1's llfr, at one curve's last maturity alone, A3's curve at
        150, and at all 535 positions, each file in the brief's form: same holds them unequal — 1, its count, and
        each differing position's line with both values whole (RP-P26's F1: an equality at 17 decimal digits and one
        within a relative 1e-18 each passed the whole suite, every such pair then equal; no two numbers the tool
        admits lie closer for their size than the largest double's integer and the integer below it)."""
        fx = Fixture(self.tmp)
        base = json.dumps(fx.outputs())
        big = int(sys.float_info.max)
        pairs = [(10 ** 100, 10 ** 100 + 1), (big, big - 1)]
        for i, (x, y) in enumerate(pairs + [(-x, -y) for x, y in pairs]):
            for where in ('llfr', 'last', 'all'):
                files = []
                for j, v in enumerate((x, y)):
                    o = json.loads(base)
                    if where == 'llfr':
                        o['A1']['llfr'] = v
                    elif where == 'last':
                        o['A3']['curve']['150'] = v
                    else:
                        for obj in o.values():
                            for k, val in obj.items():
                                obj[k] = dict.fromkeys(val, v) if isinstance(val, dict) else v
                    files.append(self.dump(f'n{i}{where}{j}.json', o))
                self.assertEqual([C.form(*C.load(f)) for f in files], [([], 535, 0)] * 2, (i, where))
                r, log = quiet(C.cmd_same, *files)
                lines, n = log.split('\n'), 535 if where == 'all' else 1
                self.assertEqual((r, len(lines), lines[3]),
                                 (1, n + 5, f'declared outputs: 535 · equal {535 - n} · differing {n}'), (i, where))
                at = {'llfr': ['A1.llfr'], 'last': ['A3.curve[150]'], 'all': ['A1.zero_rates_cc[1]', 'C1.rcs']}[where]
                self.assertEqual([lines[4], lines[-2]], [f'differs: {a}: {x} · {y}' for a in (at[0], at[-1])],
                                 (i, where))

    def test_same_holds_each_pairing_of_an_integer_and_a_floating_token_to_the_rationals_they_spell(self):
        """Two builds that differ by one pair of tokens — at one scalar alone, A2's cssr, at one curve's maturity
        alone, A1's basic_rfr at 71, and at all 535 positions —, each file in the brief's form, each pair in both
        orders and on both signs, over every pairing of the two kinds of numeric token. Unequal rationals: two
        integer tokens one unit apart — at 2**53, at the largest double's integer and at 10**100 —; an integer token
        one unit from the rational a floating token spells — 2**53 + 1 beside 9007199254740992.0, the largest
        double's integer less one beside the largest double, the integer next above 1e+100's own beside 1e+100 —;
        two floating tokens, neighbouring doubles at each of the three magnitudes: same holds each pair unequal — 1,
        its count, the first and the last differing line with both values whole. One rational in two spellings: an
        integer token beside the floating token of the same rational at each magnitude, a floating token beside
        another spelling of the same double: 0, every output equal (RP-P27's F1: an equality by the tokens' kinds —
        two integers as they are, any other pair as two floats — passed the whole suite; every unequal pair the
        suite held was of one kind, every pair of two kinds equal)."""
        fx = Fixture(self.tmp)
        shapes = {}
        for where in ('cssr', 'rfr71', 'all'):
            o = fx.outputs()
            if where == 'cssr':
                o['A2']['cssr'] = '@@T@@'
            elif where == 'rfr71':
                o['A1']['basic_rfr']['71'] = '@@T@@'
            else:
                for obj in o.values():
                    for k, val in obj.items():
                        obj[k] = dict.fromkeys(val, '@@T@@') if isinstance(val, dict) else '@@T@@'
            shapes[where] = json.dumps(o)
        at = {'cssr': ['A2.cssr'], 'rfr71': ['A1.basic_rfr[71]'], 'all': ['A1.zero_rates_cc[1]', 'C1.rcs']}
        two53, top, big = 2 ** 53, sys.float_info.max, 1e100
        up = lambda x: repr(math.nextafter(x, math.inf))
        apart = [(str(two53), str(two53 + 1)), (str(int(top)), str(int(top) - 1)), (str(10 ** 100), str(10 ** 100 + 1)),
                 (str(two53 + 1), repr(float(two53))), (str(int(top) - 1), repr(top)), (str(int(big) + 1), repr(big)),
                 (repr(float(two53)), up(float(two53))), (repr(math.nextafter(top, 0.0)), repr(top)),
                 (repr(big), up(big))]
        one = [(str(two53), repr(float(two53))), (str(int(top)), repr(top)), (str(int(big)), repr(big)),
               (repr(float(two53)), '9.007199254740992e15'), (repr(top), '17976931348623157e292'), (repr(big), '1E100')]
        floating = lambda t: bool(set(t) & set('.eE'))
        read = lambda t: float(t) if floating(t) else int(t)
        self.assertEqual([[floating(t) for t in pair] for pair in apart],
                         [[False, False]] * 3 + [[False, True]] * 3 + [[True, True]] * 3)
        self.assertEqual([[floating(t) for t in pair] for pair in one], [[False, True]] * 3 + [[True, True]] * 3)
        n = 0
        for sign in ('', '-'):
            for unequal, pairs in ((True, apart), (False, one)):
                for x, y in pairs:
                    self.assertEqual(Fraction(read(x)) != Fraction(read(y)), unequal, (x, y))
                    for where, shape in shapes.items():
                        n += 1
                        fa, fb = [self.dump(f'k{n}-{j}.json', text=shape.replace('"@@T@@"', sign + t))
                                  for j, t in enumerate((x, y))]
                        why = (sign, x, y, where)
                        self.assertEqual([C.form(*C.load(f)) for f in (fa, fb)], [([], 535, 0)] * 2, why)
                        for p, q, a, b in ((fa, fb, x, y), (fb, fa, y, x)):
                            r, log = quiet(C.cmd_same, p, q)
                            lines = log.split('\n')
                            if not unequal:
                                self.assertEqual((r, lines[3:]),
                                                 (0, ['declared outputs: 535 · equal 535 · differing 0', '']), why)
                                continue
                            k = 535 if where == 'all' else 1
                            count = f'declared outputs: 535 · equal {535 - k} · differing {k}'
                            self.assertEqual((r, len(lines), lines[3]), (1, k + 5, count), why)
                            self.assertEqual([lines[4], lines[-2]],
                                             [f'differs: {w}: {read(sign + a)!r} · {read(sign + b)!r}'
                                              for w in (at[where][0], at[where][-1])], why)
                        os.remove(fa)
                        os.remove(fb)

    def test_the_a1_file_is_never_written_over_another(self):
        fx = Fixture(self.tmp)
        out = self.path('a1.json')
        with open(out, 'w') as f:
            f.write("another's")
        with mock.patch.object(C.os.path, 'lexists', lambda p: False):
            with self.assertRaisesRegex(C.Stop, 'exists — the tool writes a new file only'):
                quiet(C.cmd_a1, self.tmp, fx.manifest, out, fx.pins, fx.msha)
        self.assertEqual(text_of(out), "another's")

    def cli(self, fx, argv, **patches):
        """The tool's command line on the fixture — its pins and manifest digest set for the run —, os's functions
        patched as given: (the exit, or the name of what it raised; what it said on stderr)."""
        err = io.StringIO()
        with contextlib.ExitStack() as st:
            st.enter_context(mock.patch.object(C, 'PINS', fx.pins))
            st.enter_context(mock.patch.object(C, 'MANIFEST_SHA256', fx.msha))
            for k, f in patches.items():
                st.enter_context(mock.patch.object(C.os, k, f))
            st.enter_context(contextlib.redirect_stdout(io.StringIO()))
            st.enter_context(contextlib.redirect_stderr(err))
            try:
                got = C.main(argv)
            except BaseException as e:
                got = type(e).__name__
        return got, err.getvalue()

    def argv(self, fx, kind, out, ok):
        return ['table', self.tmp, fx.manifest, out, '--build', 'b', ok] if kind == 'table' else \
            ['a1', self.tmp, fx.manifest, out]

    def test_every_output_at_either_edge_of_its_band(self):
        fx = Fixture(self.tmp)
        for up in (True, False):
            inside, beyond = fx.outputs(), fx.outputs()
            for k, v in fx.truth.items():
                e = t_edge(v, fx.band[k], up)
                for o, x in ((inside, e), (beyond, math.nextafter(e, math.inf if up else -math.inf))):
                    if k[2] is None:
                        o[k[0]][k[1]] = x
                    else:
                        o[k[0]][k[1]][str(k[2])] = x
            log, t = self.table(fx, [('in', self.dump(f'in{up}.json', inside)),
                                     ('beyond', self.dump(f'beyond{up}.json', beyond))], out=f't{up}')
            rows = t['table.tsv'][2]
            self.assertEqual(len(rows), 1070)
            self.assertEqual([r[3] + r[4] for r in rows if r[0] == 'in' and r[9] != 'PASS'], [])
            self.assertEqual([r[3] + r[4] for r in rows if r[0] == 'beyond' and r[9] != 'FAIL'], [])

