    def test_a_sigint_while_a_file_is_written_stops_the_run_after_that_write_and_removes_what_was_made(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_write, real_at = os.open, os.write, C.at_path
        for kind in ('table', 'a1'):
            out = self.path('wsig' + ('' if kind == 'table' else '.json'))
            created, checks, sent = [], [], []

            def op(path, flags, *a, created=created, **kw):
                if flags & os.O_CREAT:
                    created.append(path)
                return real_open(path, flags, *a, **kw)

            def write(fd, data, sent=sent):
                n = real_write(fd, data)
                if not sent:
                    sent.append(n)
                    signal.raise_signal(signal.SIGINT)
                return n

            def at(*a, checks=checks, **kw):
                checks.append(a)
                return real_at(*a, **kw)
            with mock.patch.object(C, 'at_path', at):
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, write=write)
            self.assertEqual((got, err), ('KeyboardInterrupt', f'STOP: interrupted while writing {out} — nothing it wrote '
                                                                f'is left\n'), kind)
            self.assertEqual((created, checks), (['table.tsv'] if kind == 'table' else ['wsig.json'], []), kind)
            self.assertFalse(os.path.lexists(out), kind)

