    def test_a_file_whose_making_is_cut_short_is_removed_while_held_or_named(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_fstat = os.open, os.fstat
        cases = (('identity read once more', 'error', 1, 2, None),
                 ('identity never read', 'error', 99, 2, 'made by the run, its identity not read (injected): not removed'),
                 ('a SIGINT at its identity', 'sigint', 1, 'KeyboardInterrupt', None),
                 ('a SIGINT as its creation returns', 'created', 0, 'KeyboardInterrupt', None))
        for kind in ('table', 'a1'):
            for i, (label, how, times, code, named) in enumerate(cases):
                out = self.path(f'{kind}{i}' + ('' if kind == 'table' else '.json'))
                created, left = [], [times]

                def op(path, flags, *a, how=how, **kw):
                    fd = real_open(path, flags, *a, **kw)
                    if flags & os.O_CREAT:
                        created.append(fd)
                        if how == 'created':
                            signal.raise_signal(signal.SIGINT)
                    return fd

                def fstat(fd, how=how, left=left):
                    if created and fd == created[0] and left[0]:
                        left[0] -= 1
                        if how != 'sigint':
                            raise OSError(5, 'injected')
                        signal.raise_signal(signal.SIGINT)
                    return real_fstat(fd)
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, fstat=fstat)
                self.assertEqual(got, code, label)
                self.assertEqual(err.count('STOP: '), 1, (kind, label, err))
                first = os.path.join(out, 'table.tsv') if kind == 'table' else out
                if named is None:
                    self.assertTrue(err.endswith('— nothing it wrote is left\n'), (kind, label, err))
                    self.assertFalse(os.path.lexists(out), (kind, label))
                else:
                    self.assertIn(f'left: {first} — {named}', err, (kind, label))
                    self.assertEqual(os.path.getsize(first), 0, (kind, label))
                    if kind == 'table':
                        self.assertTrue(err.endswith(f'{out} — not removed: Directory not empty\n'), (label, err))

    def test_a_close_that_fails_or_a_sigint_in_a_close_after_the_check_names_what_is_left_written_whole(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_close = os.open, os.close
        for kind in ('table', 'a1'):
            for i, how in enumerate(('error', 'sigint')):
                out = self.path(f'c{kind}{i}' + ('' if kind == 'table' else '.json'))
                created = []

                def op(path, flags, *a, **kw):
                    fd = real_open(path, flags, *a, **kw)
                    if flags & os.O_CREAT:
                        created.append(fd)
                    return fd

                def close(fd, how=how):
                    real_close(fd)
                    if created and fd == created[-1]:
                        created.clear()
                        if how == 'error':
                            raise OSError(5, 'injected')
                        signal.raise_signal(signal.SIGINT)
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, close=close)
                names = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                 if kind == 'table' else [])
                said = ('written whole and checked at its path, ' +
                        ('but its descriptors not all closed (OSError: [Errno 5] injected)' if i == 0 else
                         'its descriptors closed') + ' — no longer held, nothing removed; left: ' + '; '.join(names) + '\n')
                self.assertEqual(got, 2 if i == 0 else 'KeyboardInterrupt')
                self.assertEqual(err, (f'STOP: {out}: ' if i == 0 else f'STOP: interrupted after writing {out} — ') + said)
                for p in names[1:] or names:
                    self.assertGreater(os.path.getsize(p), 0)

    def test_a_close_in_finish_that_raises_another_class_is_named_and_the_closing_goes_on(self):
        """os.close raising a RuntimeError at the first close finish's loop makes — the newest file's —, before the
        descriptor is released or after it, table and a1: exit 2 and one stop naming the outputs as left, written
        whole and checked, and the close's failure by its class and its message; every other descriptor the run took
        closed — the loop going on —, the one whose close failed before its release alone left open."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_close = os.close

        def live():
            out = set()
            for fd in range(1024):
                try:
                    os.fstat(fd)
                    out.add(fd)
                except OSError:
                    pass
            return out

        for kind in ('table', 'a1'):
            for when in ('before', 'after'):
                out = self.path(f'rt-{kind}-{when}' + ('' if kind == 'table' else '.json'))
                fired = []

                def close(fd, when=when, fired=fired):
                    if not fired and sys._getframe(1).f_code is C.finish.__code__:
                        fired.append(fd)
                        if when == 'after':
                            real_close(fd)
                        raise RuntimeError(f'injected: the close in finish, {when} the real close')
                    return real_close(fd)
                before = live()
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), close=close)
                left = live() - before
                for fd in left:
                    os.close(fd)
                names = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                 if kind == 'table' else [])
                self.assertEqual((got, err), (2, f'STOP: {out}: written whole and checked at its path, but its '
                                              'descriptors not all closed (RuntimeError: injected: the close in '
                                              f'finish, {when} the real close) — no longer held, nothing removed; '
                                              'left: ' + '; '.join(names) + '\n'), (kind, when))
                self.assertEqual((len(fired), left), (1, set(fired) if when == 'before' else set()), (kind, when))
                for p in names[1:] or names:
                    self.assertGreater(os.path.getsize(p), 0)

    def test_every_file_the_run_makes_is_held_until_its_check_at_the_path(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_close, real_at = os.open, os.close, C.at_path
        for kind, files in (('table', 3), ('a1', 1)):
            created, events = [], []

            def op(path, flags, *a, **kw):
                fd = real_open(path, flags, *a, **kw)
                if flags & os.O_CREAT:
                    created.append(fd)
                return fd

            def close(fd):
                if fd in created:
                    events.append('close')
                real_close(fd)

            def at(*a, **kw):
                events.append('check')
                return real_at(*a, **kw)
            with mock.patch.object(C, 'at_path', at):
                got, err = self.cli(fx, self.argv(fx, kind, self.path('h' + kind), ok), open=op, close=close)
            self.assertEqual((got, err), (0, ''))
            self.assertEqual(events, ['check'] * (files + 1 if kind == 'table' else 1) + ['close'] * files, kind)

    def test_each_file_at_its_path_is_checked_after_the_last_write(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real, k = os.write, [0]
        for kind, leaves, last in (('table', ('table.tsv', 'cases.tsv', 'divergences.tsv'), 3), ('a1', ('a1.json',), 1)):
            for leaf in leaves:
                for put in ('nothing', "another's", 'a link'):
                    k[0] += 1
                    out = self.path(f'leaf{k[0]}' + ('' if kind == 'table' else '.json'))
                    at, moved, n = os.path.join(out, leaf) if kind == 'table' else out, self.path(f'moved{k[0]}'), [0]

                    def write(fd, data, at=at, moved=moved, put=put, n=n, last=last):
                        w = real(fd, data)
                        n[0] += 1
                        if n[0] == last:
                            os.rename(at, moved)
                            if put == "another's":
                                self.another(at)
                            elif put == 'a link':
                                os.symlink(moved, at)
                        return w
                    got, err = self.cli(fx, self.argv(fx, kind, out, ok), write=write)
                    left = (f'{at} — not found where the run made it' if put == 'nothing' else
                            f"{at} — another's in its place, not removed; the run's own not found there")
                    if kind == 'table' and put != 'nothing':
                        left += f'; {out} — not removed: Directory not empty'
                    self.assertEqual((got, err), (2, f'STOP: writing {out} failed (OSError: the file at its path is no '
                                                     f'longer the file the run made and wrote into) — left: {left}\n'),
                                     (kind, leaf, put))
                    self.assertGreater(os.path.getsize(moved), 0)
                    self.assertEqual(os.path.lexists(out), put != 'nothing', (kind, leaf, put))

