    def test_a_close_that_fails_or_a_sigint_in_a_close_after_a_failed_write_is_said(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_write, real_close = os.open, os.write, os.close
        for kind in ('table', 'a1'):
            for i, how in enumerate(('error', 'sigint')):
                out = self.path(f'w{kind}{i}' + ('' if kind == 'table' else '.json'))
                created, hit = [], []

                def op(path, flags, *a, created=created, **kw):
                    fd = real_open(path, flags, *a, **kw)
                    if flags & os.O_CREAT:
                        created.append(fd)
                    return fd

                def write(fd, data):
                    real_write(fd, bytes(data[:3]))
                    raise OSError(5, 'injected write fault')

                def close(fd, how=how, created=created, hit=hit):
                    real_close(fd)
                    if fd in created and not hit:
                        hit.append(fd)
                        if how == 'error':
                            raise OSError(5, 'injected close fault')
                        signal.raise_signal(signal.SIGINT)
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, write=write, close=close)
                self.assertEqual((got, err), (2 if i == 0 else 'KeyboardInterrupt',
                                              f'STOP: writing {out} failed (OSError: [Errno 5] injected write fault) — '
                                              f'nothing it wrote is left — ' +
                                              ('its descriptors not all closed (OSError: [Errno 5] injected close fault)'
                                               if i == 0 else 'interrupted before the stop was said') + '\n'), (kind, i))
                self.assertFalse(os.path.lexists(out), (kind, i))

    def test_a_sigint_once_the_parents_descriptor_is_taken_stops_the_run_before_anything_is_made(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_mkdir = os.open, os.mkdir
        for kind in ('table', 'a1'):
            out, taken, made = self.path('p' + kind + ('' if kind == 'table' else '.json')), [], []

            def op(path, flags, *a, taken=taken, made=made, **kw):
                if flags & os.O_CREAT:
                    made.append(path)
                fd = real_open(path, flags, *a, **kw)
                if flags & os.O_DIRECTORY and not flags & os.O_NOFOLLOW and not taken:
                    taken.append(fd)
                return fd

            def mkdir(path, *a, made=made, **kw):
                made.append(path)
                return real_mkdir(path, *a, **kw)

            def trace(frame, event, arg, taken=taken):
                if event == 'line' and len(taken) == 1 and frame.f_code.co_filename == C.__file__:
                    taken.append('sent')
                    signal.raise_signal(signal.SIGINT)
                return trace
            sys.settrace(trace)
            try:
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, mkdir=mkdir)
            finally:
                sys.settrace(None)
            self.assertEqual((got, err, made), ('KeyboardInterrupt', f'STOP: interrupted while writing {out} — nothing it '
                                                                     f'wrote is left\n', []), kind)
            with self.assertRaises(OSError):
                os.fstat(taken[0])
            self.assertFalse(os.path.lexists(out))

