    def sweep_phase(self, kind, case, out, names, stops):
        """The outcome of one run of the SIGINT sweep, by what it said and what it left: A — nothing said, nothing
        made; B — stopped at a look before the checks ended, what was made removed; B2 — the same, a file the run held
        named, its removal refused; C — found once the closing was done, the outputs written whole, named; D — nothing
        said, the outputs written whole; E — a failed write's stop naming the interrupt; F — a failed write's stop
        alone. None — none of these."""
        gone = not os.path.lexists(out)
        whole = all(os.path.isfile(p) and os.path.getsize(p) == 10 for p in names)
        refusal = f'left: {names[0]} — not removed: injected refusal' + (
            f'; {out} — not removed: Directory not empty' if kind == 'table' else '')
        base = (f'STOP: writing {out} failed (OSError: [Errno 5] injected write fault) — ' +
                ('nothing it wrote is left' if case == 'removed' else refusal))
        failed_left = gone if case == 'removed' else (os.path.isfile(names[0]) and os.path.getsize(names[0]) == 3)
        if not stops:
            return 'A' if gone else ('D' if case == 'written' and whole else None)
        if len(stops) != 1:
            return None
        s = stops[0]
        if s == f'STOP: interrupted while writing {out} — nothing it wrote is left' and gone:
            return 'B'
        if case == 'refused' and s == f'STOP: interrupted while writing {out} — {refusal}' and \
                os.path.isfile(names[0]) and os.path.getsize(names[0]) == 0:
            return 'B2'
        if case == 'written' and whole and s == (
                f'STOP: interrupted after writing {out} — written whole and checked at its path, its descriptors closed '
                f'— no longer held, nothing removed; left: ' + '; '.join([out] + names if kind == 'table' else names)):
            return 'C'
        if case != 'written' and failed_left and s == base + ' — interrupted before the stop was said':
            return 'E'
        if case != 'written' and failed_left and s == base:
            return 'F'
        return None

    def test_a_sigint_at_every_line_and_every_return_of_a_call_the_run_makes(self):
        """SIGINT sent at the k-th line of compare.py the writer's run runs or the k-th return of a call made from one,
        one a run, k from 1 until the run ends before it — a run that writes whole, one whose write fails and what it
        wrote is removed, one whose removal is refused: KeyboardInterrupt raised each time; at most one stop, naming the
        interrupt where a look found it — before the checks end, what was made removed or named; once the closing is
        done, the outputs written whole and named —, none when the signal came before the hold or after its last look;
        every descriptor closed; the handler before the run in place after it; the outcomes in that order, each met; a
        signal sent in a check at a path or in a write found at the look after it, one sent once the stop is composed
        raised as the hold ends."""
        real_open, real_write, real_unlink = os.open, os.write, os.unlink
        files = {'table.tsv': b't' * 10, 'cases.tsv': b'c' * 10, 'divergences.tsv': b'd' * 10}
        mine = C.__file__

        def is_open(fd):
            try:
                os.fstat(fd)
            except OSError:
                return False
            return True
        for kind in ('table', 'a1'):
            for case in ('written', 'removed', 'refused'):
                k, phases = 0, []
                order = {'written': ['A', 'B', 'C', 'D'], 'removed': ['A', 'B', 'E', 'F'],
                         'refused': ['A', 'B', 'B2', 'E', 'F']}[case]
                while True:
                    k += 1
                    self.assertLess(k, 3000)
                    out = self.path(f's-{kind}-{case}-{k}' + ('' if kind == 'table' else '.json'))
                    names = [os.path.join(out, n) for n in files] if kind == 'table' else [out]
                    taken, st, err = [], {'n': 0, 'at': None}, io.StringIO()

                    def op(path, flags, *a, taken=taken, **kw):
                        fd = real_open(path, flags, *a, **kw)
                        taken.append(fd)
                        return fd

                    def write(fd, data, case=case):
                        if case == 'written':
                            return real_write(fd, data)
                        real_write(fd, bytes(data[:3]))
                        raise OSError(5, 'injected write fault')

                    def unlink(name, *a, case=case, **kw):
                        if case == 'refused':
                            raise PermissionError(1, 'injected refusal')
                        return real_unlink(name, *a, **kw)

                    def send(where, st=st, k=k):
                        st['n'] += 1
                        if st['n'] == k:
                            st['at'] = where
                            signal.raise_signal(signal.SIGINT)

                    def trace(frame, event, arg, st=st, send=send):
                        if event == 'line' and st['at'] is None and frame.f_code.co_filename == mine:
                            send(frame.f_code.co_name)
                        return trace

                    def profile(frame, event, arg, st=st, send=send):
                        if st['at'] is not None:
                            return
                        if event == 'c_return' and frame.f_code.co_filename == mine:
                            send(frame.f_code.co_name)
                        elif event == 'return' and frame.f_back is not None and frame.f_back.f_code.co_filename == mine:
                            send(frame.f_code.co_name)
                    with contextlib.ExitStack() as es:
                        for name, f in (('open', op), ('write', write), ('unlink', unlink)):
                            es.enter_context(mock.patch.object(C.os, name, f))
                        es.enter_context(contextlib.redirect_stderr(err))
                        sys.settrace(trace)
                        sys.setprofile(profile)
                        try:
                            if kind == 'table':
                                C.write_new(out, files)
                            else:
                                C.write_new_file(out, files['table.tsv'])
                            got = 0
                        except BaseException as e:
                            got = type(e).__name__
                        finally:
                            sys.setprofile(None)
                            sys.settrace(None)
                    still = [fd for fd in taken if is_open(fd)]
                    for fd in still:
                        os.close(fd)
                    stops = [line for line in err.getvalue().split('\n') if line.startswith('STOP: ')]
                    where = (kind, case, k, st['at'])
                    self.assertIs(signal.getsignal(signal.SIGINT), signal.default_int_handler, where)
                    if st['at'] is None:
                        self.assertEqual((got, still), (0 if case == 'written' else 'Stop', []), where)
                        break
                    self.assertEqual((got, still), ('KeyboardInterrupt', []), where)
                    phase = self.sweep_phase(kind, case, out, names, stops)
                    self.assertIn(phase, order, (where, stops))
                    if st['at'] in ('at_path', 'put'):
                        self.assertEqual(phase, 'B' if case == 'written' else 'E', where)
                    if st['at'] == 'stop_says':
                        self.assertEqual(phase, 'D' if case == 'written' else 'F', where)
                    phases.append(phase)
                ranks = [order.index(p) for p in phases]
                self.assertEqual(ranks, sorted(ranks), (kind, case))
                self.assertEqual(sorted(set(phases), key=order.index), order, (kind, case))

