    def test_under_another_handler_the_run_goes_on_and_the_signal_is_passed_on(self):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_write, calls = os.write, []

        def own(signum, frame):
            calls.append(signum)
        for j, handler in enumerate((own, signal.SIG_IGN)):
            calls.clear()
            prev = signal.signal(signal.SIGINT, handler)
            try:
                for kind in ('table', 'a1'):
                    out, sent = self.path(f'h{j}{kind}' + ('' if kind == 'table' else '.json')), []

                    def write(fd, data, sent=sent):
                        if not sent:
                            sent.append(fd)
                            signal.raise_signal(signal.SIGINT)
                        return real_write(fd, data)
                    got, err = self.cli(fx, self.argv(fx, kind, out, ok), write=write)
                    self.assertEqual((got, err, signal.getsignal(signal.SIGINT)), (0, '', handler), (j, kind))
                    self.assertGreater(os.path.getsize(os.path.join(out, 'table.tsv') if kind == 'table' else out), 0)
                self.assertEqual(calls, [signal.SIGINT] * 2 if handler is own else [], j)
            finally:
                signal.signal(signal.SIGINT, prev)

    def held_lines(self, fx, kind, out, ok, so):
        """table or a1 on the fixture, stdout so, stderr read: (the return, or the name of what it raised; so; stderr's
        text)."""
        err = io.StringIO()
        with contextlib.redirect_stdout(so), contextlib.redirect_stderr(err):
            try:
                got = (C.cmd_table(self.tmp, fx.manifest, out, [('b', ok)], [], fx.pins, fx.msha) if kind == 'table'
                       else C.cmd_a1(self.tmp, fx.manifest, out, fx.pins, fx.msha))
            except BaseException as e:
                got = type(e).__name__
        return got, so, err.getvalue()

    def test_table_and_a1_say_their_own_lines_held_and_look_once_they_are_said(self):
        """SIGINT sent as table's or a1's k-th own line is written, k from 1 until the lines end before it, one a run:
        every line written, the look once they are said finding it — one stop naming the outputs, written whole and
        checked, as left, KeyboardInterrupt raised after it —; none sent: 0, no stop; a stream that fails the second
        line, a signal sent at the first: the failure's stop naming the outputs and the interrupt, KeyboardInterrupt
        after it; the handler before the run in place after each."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for kind in ('table', 'a1'):
            k, count = 0, None
            while True:
                k += 1
                self.assertLess(k, 200)
                out = self.path(f'lines-{kind}-{k}' + ('' if kind == 'table' else '.json'))
                left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                if kind == 'table' else [])
                got, so, err = self.held_lines(fx, kind, out, ok, Lines(at=k))
                where = (kind, k)
                self.assertIs(signal.getsignal(signal.SIGINT), signal.default_int_handler, where)
                self.assertTrue(all(os.path.exists(p) for p in left), where)
                count = so.n if count is None else count
                self.assertEqual((so.n, len(so.getvalue().split('\n')) - 1), (count, count), where)
                if k > count:
                    self.assertEqual((got, err), (0, ''), where)
                    break
                self.assertEqual((got, err), ('KeyboardInterrupt', f'STOP: interrupted after writing {out} and saying '
                                              f'its own lines — {HELD}' + '; '.join(left) + '\n'), where)
            self.assertGreater(count, 1, kind)
            out = self.path(f'lines-{kind}-failed' + ('' if kind == 'table' else '.json'))
            left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                            if kind == 'table' else [])
            got, so, err = self.held_lines(fx, kind, out, ok, Lines(at=1, fail=2))
            self.assertIs(signal.getsignal(signal.SIGINT), signal.default_int_handler, kind)
            self.assertEqual((got, so.n, err), ('KeyboardInterrupt', 2, f'STOP: its own lines could not be written to '
                                                f'stdout ({EPIPE}) after writing {out} — {HELD}' + '; '.join(left) +
                                                ' — interrupted before the stop was said\n'), kind)

    def child(self, fx, argv, unbuffered=False, stdout='gone', stderr='pipe'):
        """The tool run as a process of its own — form and same as its file, table and a1 by DRIVER, the fixture's pins
        and manifest digest set —; stdout a pipe whose reader has gone, not open, or a pipe read whole; stderr a pipe
        read whole, or one whose reader has gone: (the exit; stdout's bytes, or None; stderr's text, or None)."""
        tool = os.path.join(HERE, 'compare.py')
        cmd = [sys.executable, '-I', '-B'] + (['-u'] if unbuffered else []) + \
            ([tool] if argv[0] in ('form', 'same') else ['-c', DRIVER, tool, json.dumps(fx.pins), fx.msha]) + list(argv)
        gone = {}
        for which, mode in (('stdout', stdout), ('stderr', stderr)):
            if mode == 'gone':
                r, w = os.pipe()
                os.close(r)
                gone[which] = w
        try:
            p = subprocess.run(cmd, stdout=gone.get('stdout', subprocess.PIPE if stdout == 'pipe' else None),
                               stderr=gone.get('stderr', subprocess.PIPE),
                               preexec_fn=(lambda: os.close(1)) if stdout == 'closed' else None, timeout=600)
        finally:
            for w in gone.values():
                os.close(w)
        return p.returncode, p.stdout, None if p.stderr is None else p.stderr.decode('utf-8')

    def test_each_commands_own_lines_are_written_and_flushed_inside_the_runs_account(self):
        """The tool run as a process of its own, stdout a pipe whose reader has gone — buffered and under -u — or not
        open, for each command, table on a synthetic build: exit 2; stderr one stop naming the failure and, for table
        and a1, their outputs as left — the A1 file and the table's files the bytes a whole run writes —; nothing more
        on stderr: nothing left for the interpreter's own flush at exit to fail on."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        ref = self.path('ref')
        self.table(fx, [('b', ok)], out='ref')
        a1 = (json.dumps(C.a1_object(fx.oracle()[0]), indent=2, allow_nan=False) + '\n').encode('utf-8')
        for mode, unbuffered in (('gone', False), ('gone', True), ('closed', False)):
            why = EPIPE if mode == 'gone' else 'OSError: stdout is not open'
            for kind in ('form', 'same', 'a1', 'table'):
                out = self.path(f'own-{kind}-{mode}{int(unbuffered)}' + ('.json' if kind == 'a1' else ''))
                argv = {'form': ['form', ok], 'same': ['same', ok, ok], 'a1': ['a1', self.tmp, fx.manifest, out],
                        'table': ['table', self.tmp, fx.manifest, out, '--build', 'b', ok]}[kind]
                got, _, err = self.child(fx, argv, unbuffered, stdout=mode)
                stop = f'STOP: its own lines could not be written to stdout ({why})'
                if kind in ('a1', 'table'):
                    left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                    if kind == 'table' else [])
                    stop += f' after writing {out} — {HELD}' + '; '.join(left)
                self.assertEqual((got, err), (2, stop + '\n'), (kind, mode, unbuffered))
                if kind == 'a1':
                    with open(out, 'rb') as f:
                        self.assertEqual(f.read(), a1, (mode, unbuffered))
                if kind == 'table':
                    for n in ('table.tsv', 'cases.tsv', 'divergences.tsv'):
                        with open(os.path.join(out, n), 'rb') as f, open(os.path.join(ref, n), 'rb') as g:
                            self.assertEqual(f.read(), g.read(), (n, mode, unbuffered))

    def test_a_stderr_that_cannot_take_a_stop_leaves_it_unsaid_and_exits_2(self):
        """stderr a pipe whose reader has gone: a run that stops — a1 whose own lines cannot be written, form on a file
        that cannot be read — exits 2, its outputs left as written; a run with nothing to say there exits as it would."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        out = self.path('unsaid.json')
        got, _, _ = self.child(fx, ['a1', self.tmp, fx.manifest, out], stdout='gone', stderr='gone')
        self.assertEqual(got, 2)
        self.assertTrue(os.path.isfile(out))
        got, _, _ = self.child(fx, ['form', self.path('absent.json')], stdout='pipe', stderr='gone')
        self.assertEqual(got, 2)
        got, so, _ = self.child(fx, ['form', ok], stdout='pipe', stderr='gone')
        self.assertEqual((got, so.splitlines()[-1]), (0, 'FORM: conforming'.encode('utf-8')))

    def test_a_write_that_writes_fewer_bytes_than_it_was_given_is_carried_on_to_the_end(self):
        """os.write held to three bytes a call: table's files and the A1 file the bytes a whole run writes, each write
        carried on from where the last stopped."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_write, calls = os.write, []

        def short(fd, data):
            calls.append(len(data))
            return real_write(fd, bytes(data[:3]))
        for kind in ('table', 'a1'):
            whole = self.path(f'whole-{kind}' + ('' if kind == 'table' else '.json'))
            got, err = self.cli(fx, self.argv(fx, kind, whole, ok))
            self.assertEqual((got, err), (0, ''), kind)
            out = self.path(f'short-{kind}' + ('' if kind == 'table' else '.json'))
            calls.clear()
            got, err = self.cli(fx, self.argv(fx, kind, out, ok), write=short)
            self.assertEqual((got, err), (0, ''), kind)
            names = ('table.tsv', 'cases.tsv', 'divergences.tsv') if kind == 'table' else ('',)
            for n in names:
                with open(os.path.join(out, n) if n else out, 'rb') as f, \
                        open(os.path.join(whole, n) if n else whole, 'rb') as g:
                    self.assertEqual(f.read(), g.read(), (kind, n))
            self.assertGreater(len(calls), 2 * len(names), kind)

    def test_the_descriptors_are_closed_newest_first_the_parents_last(self):
        """Every descriptor the run takes closed in the order they were taken, reversed — the parent's last —, after a
        whole run and after a failed write."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_open, real_close, real_write = os.open, os.close, os.write
        for kind in ('table', 'a1'):
            for fail in (False, True):
                opened, closed = [], []

                def op(path, flags, *a, opened=opened, **kw):
                    fd = real_open(path, flags, *a, **kw)
                    opened.append(fd)
                    return fd

                def cl(fd, closed=closed):
                    closed.append(fd)
                    return real_close(fd)

                def write(fd, data, fail=fail):
                    if fail:
                        raise OSError(5, 'injected write fault')
                    return real_write(fd, data)
                out = self.path(f'order-{kind}{int(fail)}' + ('' if kind == 'table' else '.json'))
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), open=op, close=cl, write=write)
                self.assertEqual(got, 2 if fail else 0, (kind, fail))
                self.assertEqual(len(opened), {('table', False): 5, ('table', True): 3, ('a1', False): 2,
                                               ('a1', True): 2}[kind, fail], (kind, fail))
                self.assertEqual(closed, opened[::-1], (kind, fail))

    def test_a_negative_zero_keeps_its_sign_in_the_tables_value_column(self):
        fx = Fixture(self.tmp)
        o = fx.outputs()
        o['A1']['llfr'] = -0.0
        p = self.dump('negzero.json', o)
        log, t = self.table(fx, [('b', p)])
        self.assertEqual([r[7] for r in t['table.tsv'][2] if (r[2], r[3]) == ('A1', 'llfr')], ['-0.0'])
        data = C.parse(b'{"x": -0.0, "y": -0e5, "z": 0.0}')[0]
        self.assertEqual([math.copysign(1.0, data[k]) for k in 'xyz'], [-1.0, -1.0, 1.0])

    def test_a_value_of_the_officials_opposite_sign_fails_by_the_sum_of_their_magnitudes(self):
        """judge on a value and an official of opposite signs: the exact difference the sum of their magnitudes, the
        output failing; in the table, a build's value the official's negation fails its output, its difference twice
        the official's magnitude."""
        for v, o in ((-0.01915000422, 0.01915000422), (0.5, -0.25), (-3, 7)):
            self.assertEqual(C.judge(v, o, C.EXACT), (False, abs(Fraction(v)) + abs(Fraction(o))), (v, o))
        fx = Fixture(self.tmp)
        o = fx.outputs()
        v = o['A1']['llfr']
        o['A1']['llfr'] = -v
        log, t = self.table(fx, [('b', self.dump('opposite.json', o))])
        self.assertEqual([(r[7], r[8], r[9]) for r in t['table.tsv'][2] if (r[2], r[3]) == ('A1', 'llfr')],
                         [(repr(-v), C.sig3(2 * abs(Fraction(v))), 'FAIL')])

    def test_minus_1e400_fails_as_1e400_does_in_the_parser_the_form_and_the_table(self):
        """-1e400 past the double range as 1e400 is: a non-number in the parser, a deviation in the form, a failing
        output in the table — the table made whole."""
        data = C.parse(b'{"x": -1e400, "y": 1e400}')[0]
        self.assertEqual([type(data[k]) for k in 'xy'], [C.NonNumber, C.NonNumber])
        fx = Fixture(self.tmp)
        for token in ('-1e400', '1e400'):
            o = fx.outputs()
            o['A1']['llfr'] = 'PLACE'
            p = self.dump(f'past{token}.json', text=json.dumps(o, indent=1).replace('"PLACE"', token))
            r, log = quiet(C.cmd_form, p, False)
            self.assertEqual((r, f'{token}, past the double range' in log), (1, True), token)
            log, t = self.table(fx, [('b', p)], out=f't{token}')
            self.assertEqual([(r[9], r[10]) for r in t['table.tsv'][2] if (r[2], r[3]) == ('A1', 'llfr')],
                             [('FAIL', f'non-numeric: {token}, past the double range')], token)

    def test_the_parsers_finite_endpoints_and_its_subnormals_are_the_doubles_they_parse_to(self):
        """A builder's ±1.7976931348623157e+308 — the largest finite double — admitted: form conforming, same equal,
        and in a table whose official value is that double, at E2 'RCS'!G11 — B1's w_gov —, its row passing by
        0.00e+00; a builder's ±5e-324 — the least subnormal — kept: same holding it unequal to 0.0, and in a table
        whose official value is it, its row's value that double and its difference 0.00e+00."""
        for sign in (1, -1):
            for v in (sign * sys.float_info.max, sign * 5e-324):
                tag = f'{"minus" if sign < 0 else "plus"}-{"max" if abs(v) > 1 else "tiny"}'
                folder = self.path(tag)
                os.mkdir(folder)
                fx = Fixture(folder, official=('E2', 'G11', f'><v>{v!r}</v></c>', v))
                o = fx.outputs()
                self.assertEqual(o['B1']['w_gov'], v)
                p = self.dump(f'{tag}.json', o)
                if abs(v) > 1:
                    self.assertEqual(C.form(*C.load(p)), ([], 535, 0), tag)
                    r, log = quiet(C.cmd_same, p, p)
                    self.assertEqual((r, 'declared outputs: 535 · equal 535 · differing 0' in log), (0, True), tag)
                else:
                    o['B1']['w_gov'] = 0.0
                    q = self.dump(f'{tag}-zero.json', o)
                    r, log = quiet(C.cmd_same, p, q)
                    self.assertEqual((r, 'declared outputs: 535 · equal 534 · differing 1' in log), (1, True), tag)
                r, log = quiet(C.cmd_table, folder, fx.manifest, self.path(f't-{tag}'), [('b', p)], [], fx.pins,
                               fx.msha)
                rows = read_tsv(self.path(f't-{tag}', 'table.tsv'))[2]
                self.assertEqual((r, [x[7:10] for x in rows if (x[2], x[3]) == ('B1', 'w_gov')]),
                                 (0, [[repr(v), '0.00e+00', 'PASS']]), tag)

    def test_a_decimal_token_is_judged_as_the_double_it_parses_to_and_an_integer_token_on_its_digits(self):
        """At the edge of the double range, on both signs, a build's B1 w_gov one of five tokens, the official
        value there — E2 'RCS'!G11 — the largest double of that sign: the decimal tokens 1.7976931348623157e308 —
        the largest double as written — and 1.7976931348623158e308 — above the largest double's integer as
        written, the largest double as parsed — each admitted: form conforming, the table's row that double,
        0.00e+00, PASS, same of the file with itself 0; 1.7976931348623159e308 — infinite as parsed — refused: one
        deviation naming the token, the row failing by it, same of the file with itself 1. The integer token of the
        largest double's integer admitted, its row passing by 0.00e+00; the integer token one above it refused on
        its digits, named shortened — though the double it would parse to is the largest. And the three admitted
        spellings one rational: same on each two of them 0 (RP-P27's F5: the integers' bound laid on a decimal token
        passed the whole suite — the token ending 158e308 then refused; the suite's decimal tokens at the edge were
        the doubles' own shortest spellings)."""
        top = int(sys.float_info.max)
        short = lambda s: s if len(s) <= 24 else f'{s[:8]}…{s[-4:]} ({len(s)} characters)'
        for sign in ('', '-'):
            v = float(sign + repr(sys.float_info.max))
            folder = self.path('edge-' + ('minus' if sign else 'plus'))
            os.mkdir(folder)
            fx = Fixture(folder, official=('E2', 'G11', f'><v>{v!r}</v></c>', v))
            o = fx.outputs()
            self.assertEqual(o['B1']['w_gov'], v)
            o['B1']['w_gov'] = '@@T@@'
            shape = json.dumps(o, indent=1)
            tokens = [(sign + '1.7976931348623157e308', repr(v)), (sign + '1.7976931348623158e308', repr(v)),
                      (sign + '1.7976931348623159e308', None), (sign + str(top), sign + str(top)),
                      (sign + str(top + 1), None)]
            self.assertEqual([math.isfinite(float(t)) for t, _ in tokens], [True, True, False, True, True])
            self.assertEqual([abs(Fraction(t)) > top for t, _ in tokens], [False, True, True, False, True])
            admitted = []
            for i, (t, value) in enumerate(tokens):
                tag = f'{"minus" if sign else "plus"}-{i}'
                p = self.dump(f'edge-{tag}.json', text=shape.replace('"@@T@@"', t))
                why = f'non-numeric: {short(t)}, past the double range'
                first = f"{p} · sha256 {sha(p)} · against the brief's form (item 1)"
                want = (0, [first, 'numbers where the form expects one: 535 of 535', 'FORM: conforming', '']) \
                    if value else (1, [first, 'numbers where the form expects one: 534 of 535',
                                       f'deviation: B1.w_gov: {why}', 'FORM: 1 deviation(s)', ''])
                r, log = quiet(C.cmd_form, p, False)
                self.assertEqual((r, log.split('\n')), want, t)
                r, log = quiet(C.cmd_table, folder, fx.manifest, self.path(f't-{tag}'), [('b', p)], [], fx.pins,
                               fx.msha)
                rows = read_tsv(self.path(f't-{tag}', 'table.tsv'))[2]
                self.assertEqual((r, [x[7:11] for x in rows if (x[2], x[3]) == ('B1', 'w_gov')]),
                                 (0, [[value, '0.00e+00', 'PASS', ''] if value else ['-', '-', 'FAIL', why]]), t)
                r, log = quiet(C.cmd_same, p, p)
                k = 0 if value else 1
                self.assertEqual((r, log.split('\n')[3]),
                                 (k, f'declared outputs: 535 · equal {535 - k} · differing {k}'), t)
                if value:
                    admitted.append(p)
            for p in admitted:
                for q in admitted:
                    r, log = quiet(C.cmd_same, p, q)
                    self.assertEqual((r, log.split('\n')[3]), (0, 'declared outputs: 535 · equal 535 · differing 0'),
                                     (sign, p, q))

    def test_a_decimal_token_is_admitted_by_its_double_alone_whatever_its_length(self):
        """At a scalar — B1's w_gov, E2 'RCS'!G11 — and at a curve's maturity — A1's basic_rfr at 71, E1's L95 —, on
        both signs, the official value at both 1.23456789012345e-2 or a zero of that sign, the curve's cell, the
        workbook's pin, the manifest's row and its digest made again: a build's token there of more than MAX_DIGITS
        characters — MAX_DIGITS + 1 and four times MAX_DIGITS, the sign apart — whose double is the official value —
        its shortest spelling with zeros after its fraction's digits, and with zeros at the head of its exponent; the
        zero as 0. and as 0e, each followed by zeros —: form conforming, the table's row that double, 0.00e+00, PASS,
        no other row of the build failing, same against the file in its short spellings 0. Beside them a token of
        each length past the double range — 1., zeros, e309 — refused as the tool refuses it: one deviation naming it
        shortened, its row failing by it and no other, same against the short spellings 1 (the sweep's S0781 on
        revision 123's bytes: as_float's admission held to the integers' bound on its digits passed the whole suite —
        no test gave the parser a decimal token longer than MAX_DIGITS)."""
        D = C.MAX_DIGITS
        short = lambda s: s if len(s) <= 24 else f'{s[:8]}…{s[-4:]} ({len(s)} characters)'
        places = (('B1', 'w_gov', None), ('A1', 'basic_rfr', 71))
        for sign in ('', '-'):
            for zero in (False, True):
                v = float(sign + ('0.0' if zero else '1.23456789012345e-2'))
                tag = ('minus' if sign else 'plus') + ('-zero' if zero else '')
                folder = self.path('length-' + tag)
                os.mkdir(folder)
                fx = Fixture(folder, official=('E2', 'G11', f'><v>{v!r}</v></c>', v))
                cells = [(f'L{25 + i}', fx.truth[('A1', 'basic_rfr', i + 1)]) for i in range(150)]
                fx.edit('E1', 'xl/worksheets/sheet1.xml', ('<c r="L95"' + fnum(cells[70][1]), '<c r="L95"' + fnum(v)))
                old = f"'{IDE_}'!L25:L174 · all · 150 · {tdigest(IDE_, cells)}"
                new = f"'{IDE_}'!L25:L174 · all · 150 · {tdigest(IDE_, cells[:70] + [('L95', v)] + cells[71:])}"
                lines = text_of(fx.manifest)
                self.assertEqual((lines.count(old), lines.count(new)), (1, 0), tag)
                with open(fx.manifest, 'w', encoding='utf-8') as f:
                    f.write(lines.replace(old, new))
                fx.msha = sha(fx.manifest)
                fx.truth[('A1', 'basic_rfr', 71)] = v
                ref = self.dump(f'length-{tag}-short.json', fx.outputs())
                tokens = []
                for n in (D + 1, 4 * D):
                    if zero:
                        tokens += [(sign + '0.' + '0' * (n - 2), True), (sign + '0e' + '0' * (n - 2), True)]
                    else:
                        tokens += [(sign + repr(abs(v)).ljust(n, '0'), True),
                                   (sign + '1.23456789012345e-' + '0' * (n - 19) + '2', True),
                                   (sign + '1.' + '0' * (n - 6) + 'e309', False)]
                for t, admitted in tokens:
                    x = float(t)
                    self.assertEqual((len(t.lstrip('-')) > D, t.startswith('-') == bool(sign),
                                      ((x, math.copysign(1.0, x)) == (v, math.copysign(1.0, v))) if admitted
                                      else math.isinf(x)), (True, True, True), t[:24])
                builds = []
                for t, admitted in tokens:
                    for case, key, m in places:
                        o = fx.outputs()
                        if m is None:
                            o[case][key] = '@@T@@'
                        else:
                            o[case][key][str(m)] = '@@T@@'
                        name = f'b{len(builds) + 1}'
                        p = self.dump(f'length-{tag}-{name}.json', text=json.dumps(o, indent=1).replace('"@@T@@"', t))
                        builds.append((name, p, t, admitted, case, key, m))
                out = self.path(f'length-{tag}-table')
                r, log = quiet(C.cmd_table, folder, fx.manifest, out, [b[:2] for b in builds], [], fx.pins, fx.msha)
                rows = read_tsv(os.path.join(out, 'table.tsv'))[2]
                self.assertEqual((r, len(rows)), (0, 535 * len(builds)), tag)
                for name, p, t, admitted, case, key, m in builds:
                    why = f'non-numeric: {short(t)}, past the double range'
                    where = f'{case}.{key}' + ('' if m is None else f'.{m}')
                    first = f"{p} · sha256 {sha(p)} · against the brief's form (item 1)"
                    want = (0, [first, 'numbers where the form expects one: 535 of 535', 'FORM: conforming', '']) \
                        if admitted else (1, [first, 'numbers where the form expects one: 534 of 535',
                                              f'deviation: {where}: {why}', 'FORM: 1 deviation(s)', ''])
                    r, log = quiet(C.cmd_form, p, False)
                    self.assertEqual((r, log.split('\n')), want, (tag, name, t[:24]))
                    at = '-' if m is None else str(m)
                    here = [x[7:11] for x in rows if x[0] == name and (x[2], x[3], x[4]) == (case, key, at)]
                    failing = [x[2:5] for x in rows if x[0] == name and x[9] != 'PASS']
                    self.assertEqual((here, failing), ([[repr(v), '0.00e+00', 'PASS', '']], []) if admitted
                                     else ([['-', '-', 'FAIL', why]], [[case, key, at]]), (tag, name, t[:24]))
                    k = 0 if admitted else 1
                    r, log = quiet(C.cmd_same, p, ref)
                    self.assertEqual((r, log.split('\n')[3]),
                                     (k, f'declared outputs: 535 · equal {535 - k} · differing {k}'),
                                     (tag, name, t[:24]))

    def test_each_conversion_of_a_decimal_token_is_held_against_an_intervening_decimal_rounding(self):
        """At a scalar — B1's w_gov, E2 'RCS'!G11 — and at a curve's maturity — A1's basic_rfr at 71, E1's L95 —, on
        both signs, about 2**25 and its upper neighbour, whose exact midpoint is 33554432.0000000037252902984619140625:
        the midpoint itself — binary64 rounds it half to even, to 2**25 —, a token just below it and one just above
        it, each short and each of 312 characters, every one a token whose double a decimal rounding to 15, 16 or 17
        significant digits first would change. A build's token there, the official 2**25 of that sign, the curve's
        cell, the workbook's pin, the manifest's row and its digest made again: form conforming; same against the
        build in the token's own double's shortest spelling 0, against its neighbour's 1 with its line; the table's
        row the token's double — 2**25 at 0.00e+00, PASS; its neighbour at 7.45e-09, by the band —, no other row of
        the build failing. The same tokens as the official's cached text at both places, the manifest's value the
        token's double: a1 0, the A1 file's value at 71 that double; the table 0, both rows that double at 0.00e+00,
        PASS, no row failing (RP-P28's F1: as_float's conversion and the cached reader number's, each through a
        17-digit decimal rounding, passed the whole suite — no test gave either a token whose double such a rounding
        changes)."""
        d = 2.0 ** 25
        up = math.nextafter(d, math.inf)
        mid = '33554432.0000000037252902984619140625'
        self.assertEqual((Fraction(mid), Fraction(up) - Fraction(d)),
                         ((Fraction(d) + Fraction(up)) / 2, Fraction(1, 2 ** 27)))
        spelled = [(mid, d), (mid + '0' * 275, d), (mid[:-1], d), (mid[:-1] + '4' + '9' * 275, d),
                   (mid[:-1] + '6', up), (mid + '0' * 274 + '1', up)]
        self.assertEqual([len(t) for t, _ in spelled], [37, 312, 36, 312, 37, 312])
        for t, x in spelled:
            self.assertEqual(float(t), x, t[:40])
            self.assertTrue(any(float(format(decimal.Decimal(t), f'.{n}g')) != x for n in (15, 16, 17)), t[:40])
        places = (('B1', 'w_gov', None), ('A1', 'basic_rfr', 71))

        def at71(fx, xml, x):
            cells = [(f'L{25 + i}', fx.truth[('A1', 'basic_rfr', i + 1)]) for i in range(150)]
            fx.edit('E1', 'xl/worksheets/sheet1.xml', ('<c r="L95"' + fnum(cells[70][1]), '<c r="L95"' + xml))
            old = f"'{IDE_}'!L25:L174 · all · 150 · {tdigest(IDE_, cells)}"
            new = f"'{IDE_}'!L25:L174 · all · 150 · {tdigest(IDE_, cells[:70] + [('L95', x)] + cells[71:])}"
            lines = text_of(fx.manifest)
            self.assertEqual((lines.count(old), lines.count(new)), (1, 0))
            with open(fx.manifest, 'w', encoding='utf-8') as f:
                f.write(lines.replace(old, new))
            fx.msha = sha(fx.manifest)
            fx.truth[('A1', 'basic_rfr', 71)] = x

        def shaped(fx, case, key, m, t):
            o = fx.outputs()
            if m is None:
                o[case][key] = '@@T@@'
            else:
                o[case][key][str(m)] = '@@T@@'
            return json.dumps(o, indent=1).replace('"@@T@@"', t)

        for sign in ('', '-'):
            v, vu = float(sign + repr(d)), float(sign + repr(up))
            tag = 'minus' if sign else 'plus'
            folder = self.path('round-' + tag)
            os.mkdir(folder)
            fx = Fixture(folder, official=('E2', 'G11', f'><v>{v!r}</v></c>', v))
            at71(fx, fnum(v), v)
            builds, refs = [], {}
            for case, key, m in places:
                for y in (v, vu):
                    refs[(case, key, y)] = self.dump(f'round-{tag}-{case}-{y!r}.json',
                                                     text=shaped(fx, case, key, m, repr(y)))
                for t, x in spelled:
                    name = f'b{len(builds) + 1}'
                    p = self.dump(f'round-{tag}-{name}.json', text=shaped(fx, case, key, m, sign + t))
                    builds.append((name, p, float(sign + repr(x)), case, key, m))
            out = self.path(f'round-{tag}-table')
            r, log = quiet(C.cmd_table, folder, fx.manifest, out, [b[:2] for b in builds], [], fx.pins, fx.msha)
            rows = read_tsv(os.path.join(out, 'table.tsv'))[2]
            self.assertEqual((r, len(rows)), (0, 535 * len(builds)), tag)
            for name, p, x, case, key, m in builds:
                why = (tag, name, case, key)
                self.assertEqual(C.form(*C.load(p)), ([], 535, 0), why)
                other = vu if x == v else v
                where = f'{case}.{key}' + ('' if m is None else f'[{m}]')
                r, log = quiet(C.cmd_same, p, refs[(case, key, x)])
                self.assertEqual((r, log.split('\n')[3]), (0, 'declared outputs: 535 · equal 535 · differing 0'), why)
                r, log = quiet(C.cmd_same, p, refs[(case, key, other)])
                lines = log.split('\n')
                self.assertEqual((r, lines[3], lines[4]), (1, 'declared outputs: 535 · equal 534 · differing 1',
                                                           f'differs: {where}: {x!r} · {other!r}'), why)
                op, band = fx.band[(case, key, m)]
                gap = Fraction(1, 2 ** 27)
                ok = x == v or (gap <= Fraction(band) if op == '<=' else gap < Fraction(band))
                at = '-' if m is None else str(m)
                want = [repr(x), '0.00e+00' if x == v else '7.45e-09', 'PASS' if ok else 'FAIL',
                        '' if ok else 'outside its band']
                here = [y[7:11] for y in rows if y[0] == name and (y[2], y[3], y[4]) == (case, key, at)]
                failing = [y[2:5] for y in rows if y[0] == name and y[9] != 'PASS']
                self.assertEqual((here, failing), ([want], [] if ok else [[case, key, at]]), why)
            for i, (t, x0) in enumerate(spelled):
                x = float(sign + repr(x0))
                cached = f'><f>X1+1</f><v>{sign}{t}</v></c>'
                folder = self.path(f'cache-{tag}-{i}')
                os.mkdir(folder)
                fx = Fixture(folder, official=('E2', 'G11', cached, x))
                at71(fx, cached, x)
                why = (tag, i, len(t))
                a1 = self.path(f'cache-{tag}-{i}.json')
                r, log = quiet(C.cmd_a1, folder, fx.manifest, a1, fx.pins, fx.msha)
                with open(a1, encoding='utf-8') as f:
                    self.assertEqual((r, json.load(f)['basic_rfr']['71']), (0, x), why)
                b = self.dump(f'cache-{tag}-{i}-build.json', fx.outputs())
                out = self.path(f'cache-{tag}-{i}-table')
                r, log = quiet(C.cmd_table, folder, fx.manifest, out, [('b', b)], [], fx.pins, fx.msha)
                rows = read_tsv(os.path.join(out, 'table.tsv'))[2]
                self.assertEqual((r, [y[7:11] for y in rows if (y[2], y[3], y[4]) in (('A1', 'basic_rfr', '71'),
                                                                                      ('B1', 'w_gov', '-'))],
                                  [y[2:5] for y in rows if y[9] != 'PASS']),
                                 (0, [[repr(x), '0.00e+00', 'PASS', '']] * 2, []), why)

    def test_quiet_leaves_no_descriptor_of_its_own_open(self):
        """quiet on a stream with a descriptor of its own: that descriptor pointed at the null device, what the stream
        then writes going nowhere, no other descriptor left open; where the null device's descriptor takes the stream's
        own number — the stream's descriptor closed before —, it stays open as the stream's; where os.dup2 fails, or
        the stream has no descriptor — a StringIO —, or is none, the stream closed and no descriptor left open."""
        null = os.stat(os.devnull)

        def live():
            out = set()
            for fd in range(1024):
                try:
                    os.fstat(fd)
                    out.add(fd)
                except OSError:
                    pass
            return out

        def is_null(fd):
            st = os.fstat(fd)
            return (st.st_dev, st.st_ino) == (null.st_dev, null.st_ino)
        p = self.path('quiet-a.txt')
        with open(p, 'w') as f:
            before = live()
            C.quiet(f)
            self.assertEqual((live(), is_null(f.fileno()), f.closed), (before, True, False))
            f.write('goes nowhere\n')
        self.assertEqual(os.path.getsize(p), 0)
        low = min(set(range(1024)) - live())
        fd = os.open(self.path('quiet-b.txt'), os.O_WRONLY | os.O_CREAT, 0o600)
        if fd != low:
            os.dup2(fd, low)
            os.close(fd)
        f = open(low, 'w')
        os.close(low)
        before = live()
        C.quiet(f)
        self.assertEqual((live(), is_null(low), f.closed), (before | {low}, True, False))
        f.close()
        with open(self.path('quiet-c.txt'), 'w') as f:
            k = f.fileno()
            before = live()
            with mock.patch.object(C.os, 'dup2', side_effect=OSError(errno.EBADF, 'injected dup2 fault')):
                C.quiet(f)
            self.assertEqual((live(), f.closed), (before - {k}, True))
        s = io.StringIO()
        before = live()
        C.quiet(s)
        with mock.patch.object(sys, 'stdout', sys.stdout), mock.patch.object(sys, 'stderr', sys.stderr):
            C.quiet(None)
        self.assertEqual((live(), s.closed), (before, True))

    def test_an_array_formulas_member_cells_are_derived_and_left_out_under_const(self):
        """A cell inside an array formula's range carries no formula of its own: derived — left out under 'const',
        kept under 'all' —, as the cell that holds the formula is."""
        p = self.path('array.xlsm')
        write_book(p, {'S': {'A1': '><f t="array" ref="A1:A3">B1:B3*2</f><v>1</v></c>', 'A2': num(2), 'A3': num(3),
                             'A4': num(4)}})
        book = C.Book(p)
        self.assertEqual(book.cells('S', 'A1:A4', 'const'), [('A4', 4)])
        self.assertEqual(book.cells('S', 'A1:A4', 'all'), [('A1', 1), ('A2', 2), ('A3', 3), ('A4', 4)])

    def test_say_writes_through_stdouts_descriptor_every_byte_counted(self):
        """say with stdout a stream over a file: what its buffer held written first, then the lines, encoded by the
        stream's own encoding; os.write held to three bytes a call — every byte written, carried on; a write that
        writes no byte — a Stop naming it, the stream's descriptor then pointed at the null device; a stream with no
        descriptor written line by line and flushed after the last line."""
        lines = ['a · b', 'second line']
        size = len('a · b\nsecond line\n'.encode('utf-8'))
        null = os.stat(os.devnull)
        p = self.path('say-a.txt')
        with open(p, 'w', encoding='latin-1') as f, mock.patch.object(sys, 'stdout', f):
            f.write('before\n')
            C.say(lines)
        with open(p, 'rb') as f:
            self.assertEqual(f.read(), b'before\na \xb7 b\nsecond line\n')
        real_write, calls = os.write, []

        def short(fd, data):
            calls.append(len(data))
            return real_write(fd, bytes(data[:3]))
        p = self.path('say-b.txt')
        with open(p, 'w', encoding='utf-8') as f, mock.patch.object(sys, 'stdout', f), \
                mock.patch.object(C.os, 'write', short):
            C.say(lines)
        with open(p, 'rb') as f:
            self.assertEqual(f.read(), 'a · b\nsecond line\n'.encode('utf-8'))
        self.assertGreater(len(calls), 3)
        with open(self.path('say-c.txt'), 'w', encoding='utf-8') as f, mock.patch.object(sys, 'stdout', f):
            with mock.patch.object(C.os, 'write', lambda fd, data: 0), self.assertRaises(C.Stop) as cm:
                C.say(lines)
            st = os.fstat(f.fileno())
            self.assertEqual((str(cm.exception), (st.st_dev, st.st_ino)),
                             ('its own lines could not be written to stdout (OSError: a write to its descriptor wrote '
                              f'no byte, {size} B left)',
                              (null.st_dev, null.st_ino)))

        class Rec:
            def __init__(self):
                self.calls = []

            def write(self, s):
                self.calls.append(('write', s))
                return len(s)

            def flush(self):
                self.calls.append(('flush',))
        rec = Rec()
        with mock.patch.object(sys, 'stdout', rec):
            C.say(lines)
        self.assertEqual(rec.calls, [('write', 'a · b\n'), ('write', 'second line\n'), ('flush',)])

    def native(self, fx, kind, ok, stdout, tag):
        """kind — form, same, a1 or table, table on the build ok — run by main, the fixture's pins and manifest digest
        set, stdout the stream given, stderr captured: (the exit; stderr's text and, where stdout is a StringIO, its
        text, each with the output's path read as <out>; the output's path)."""
        out = self.path(f'native-{kind}-{tag}' + ('.json' if kind == 'a1' else ''))
        argv = {'form': ['form', ok], 'same': ['same', ok, ok]}.get(kind) or self.argv(fx, kind, out, ok)
        err = io.StringIO()
        with contextlib.ExitStack() as st:
            st.enter_context(mock.patch.object(C, 'PINS', fx.pins))
            st.enter_context(mock.patch.object(C, 'MANIFEST_SHA256', fx.msha))
            st.enter_context(mock.patch.object(sys, 'stdout', stdout))
            st.enter_context(contextlib.redirect_stderr(err))
            got = C.main(argv)
        said = stdout.getvalue().replace(out, '<out>') if isinstance(stdout, io.StringIO) else None
        return got, err.getvalue().replace(out, '<out>'), said, out

    def test_say_continues_a_stateful_encoders_stream_for_each_command(self):
        """Each command — form, same, a1 and table, table on a synthetic build — run by main, stdout a stream over a
        file whose encoding marks its start or carries a state from one write to the next — utf-8-sig and utf-16 after
        'before\\n', iso2022_jp after '日本' —, errors 'backslashreplace', the prefix still in the stream's buffer: the
        file's bytes one stream's — the prefix and the command's lines as one encoder writes them —, the exit and
        stderr those of a run whose stdout has no descriptor; such a stream whose binary layer is a raw file — no
        buffer holding the account of what its encoder writes, as under -u —: exit 2 and one stop naming it, for a1
        and table their outputs named as left, the prefix alone in the file."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for kind in ('form', 'same', 'a1', 'table'):
            got0, err0, said, _ = self.native(fx, kind, ok, io.StringIO(), 'plain')
            self.assertEqual((got0, err0), (0, ''), kind)
            for encoding, prefix in (('utf-8-sig', 'before\n'), ('utf-16', 'before\n'), ('iso2022_jp', '日本')):
                p = self.path(f'stateful-{kind}-{encoding}.txt')
                with open(p, 'w', encoding=encoding, errors='backslashreplace') as f:
                    f.write(prefix)
                    got, err, _, out = self.native(fx, kind, ok, f, encoding)
                with open(p, 'rb') as f:
                    data = f.read()
                self.assertEqual((got, err), (got0, err0), (kind, encoding))
                self.assertEqual(data, (prefix + said.replace('<out>', out)).encode(encoding, 'backslashreplace'),
                                 (kind, encoding))
            p = self.path(f'stateful-{kind}-raw.txt')
            f = io.TextIOWrapper(io.FileIO(p, 'w'), encoding='utf-16', errors='backslashreplace', write_through=True)
            try:
                f.write('before\n')
                got, err, _, out = self.native(fx, kind, ok, f, 'raw')
            finally:
                f.close()
            stop = ('STOP: its own lines could not be written to stdout (OSError: its encoding utf-16 marks its '
                    'start or carries a state, and its binary layer — FileIO — cannot hold the account of every byte '
                    'its encoder writes)')
            if kind in ('a1', 'table'):
                left = ['<out>'] + ([f'<out>/{n}' for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                    if kind == 'table' else [])
                stop += f' after writing <out> — {HELD}' + '; '.join(left)
            self.assertEqual((got, err), (2, stop + '\n'), kind)
            with open(p, 'rb') as g:
                self.assertEqual(g.read(), 'before\n'.encode('utf-16'), kind)

    def test_a_native_stdouts_error_policy_is_its_own_for_each_command(self):
        """Each command — form, same, a1 and table, table on a synthetic build — run by main, stdout a stream over a
        file in ascii with errors 'backslashreplace', the command's own lines holding characters past ascii: exit 0,
        stderr empty, the file's bytes the lines encoded by that policy, each such character escaped."""
