    def test_each_commands_lines_go_out_by_a_native_stdouts_own_policy_or_stop_where_it_refuses_a_character(self):
        """Each command — form, same, a1 and table, table on a synthetic build — run by main, stdout a native stream
        over a file in ascii and in latin-1 — stateless encodings —, under each error policy the text layer names
        — strict, ignore, replace, xmlcharrefreplace, backslashreplace, namereplace, surrogateescape and
        surrogatepass —, over a buffered writer and over a raw file — no buffer of its own, as under -u —, the
        command's own lines holding characters past ascii: where that encoding and policy take every character of
        the lines, exit 0, stderr empty, the file's bytes the lines encoded by them; where the policy refuses one,
        exit 2, one stop naming the encoder's own error, for a1 and table their outputs named as left, no byte in
        the file (RP-P27's F3: say's policy fixed at 'backslashreplace' passed the whole suite — every policy the
        suite had given a stateless stream was that one; over a raw file the lines encoded by another policy were
        then taken for a stream's state, a stop; over a buffered writer the stream's own encoder hid it)."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        strict = ('strict', 'surrogateescape', 'surrogatepass')
        policies = strict + ('ignore', 'replace', 'xmlcharrefreplace', 'backslashreplace', 'namereplace')
        files = ('table.tsv', 'cases.tsv', 'divergences.tsv')
        seen = set()
        for kind in ('form', 'same', 'a1', 'table'):
            got0, err0, said, _ = self.native(fx, kind, ok, io.StringIO(), 'plain')
            self.assertEqual((got0, err0, any(ord(c) > 127 for c in said)), (0, '', True), kind)
            for encoding in ('ascii', 'latin-1'):
                for policy in policies:
                    for layer in ('buffered', 'raw'):
                        tag = f'{encoding}-{policy}-{layer}'
                        p = self.path(f'policy-{kind}-{tag}.txt')
                        f = open(p, 'w', encoding=encoding, errors=policy) if layer == 'buffered' else \
                            io.TextIOWrapper(io.FileIO(p, 'w'), encoding=encoding, errors=policy, write_through=True)
                        try:
                            got, err, _, out = self.native(fx, kind, ok, f, tag)
                        finally:
                            f.close()
                        with open(p, 'rb') as g:
                            data = g.read()
                        try:
                            want = (0, '', said.replace('<out>', out).encode(encoding, policy))
                        except UnicodeEncodeError as e:
                            stop = f'STOP: its own lines could not be written to stdout (UnicodeEncodeError: {e})'
                            if kind in ('a1', 'table'):
                                left = ['<out>'] + ([f'<out>/{n}' for n in files] if kind == 'table' else [])
                                stop += f' after writing <out> — {HELD}' + '; '.join(left)
                            want = (2, stop + '\n', b'')
                        seen.add((encoding, policy, want[0]))
                        self.assertEqual((got, err, data), want, (kind, tag))
        self.assertEqual(sorted(k for k in seen if k[0] == 'ascii'),
                         sorted(('ascii', p, 2 if p in strict else 0) for p in policies))
        self.assertEqual({k[2] for k in seen if k[0] == 'latin-1' and k[1] not in strict}, {0})

