    def test_each_commands_lines_go_through_an_exact_native_buffered_random_as_one_continuous_encoding(self):
        """Each command — form, same, a1 and table, table on a synthetic build — run by main, stdout a native stream
        opened 'w+' — its binary layer an exact native BufferedRandom — under each stateful encoding the tests use:
        utf-8-sig and utf-16 after 'before\\n', iso2022_jp after '日本', iso2022_jp_2 after '한' and iso2022_jp_ext
        after 'ｱ', each still in the stream's buffer; big5hkscs after 'Ê', shift_jis_2004 and euc_jis_2004 after
        'か', each written, the stream flushed and no byte of it in the file yet —, errors 'backslashreplace': exit
        0, stderr empty, the file's bytes the prefix and the command's lines as one encoder writes them (RP-P28's F3:
        the admitted native BufferedRandom deleted from stateful's layers passed the whole suite — every admitted
        native stream the suite gave a stateful encoding was opened 'w', a BufferedWriter)."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        held = (('big5hkscs', 'Ê'), ('shift_jis_2004', 'か'), ('euc_jis_2004', 'か'))
        pieces = (('utf-8-sig', 'before\n'), ('utf-16', 'before\n'), ('iso2022_jp', '日本'), ('iso2022_jp_2', '한'),
                  ('iso2022_jp_ext', 'ｱ')) + held
        for kind in ('form', 'same', 'a1', 'table'):
            got0, err0, said, _ = self.native(fx, kind, ok, io.StringIO(), 'plain')
            self.assertEqual((got0, err0), (0, ''), kind)
            for encoding, prefix in pieces:
                p = self.path(f'random-{kind}-{encoding}.txt')
                with open(p, 'w+', encoding=encoding, errors='backslashreplace') as f:
                    self.assertIs(type(f.buffer), io.BufferedRandom)
                    f.write(prefix)
                    if (encoding, prefix) in held:
                        f.flush()
                    self.assertEqual(os.path.getsize(p), 0, (kind, encoding))
                    got, err, _, out = self.native(fx, kind, ok, f, 'random-' + encoding)
                with open(p, 'rb') as g:
                    data = g.read()
                self.assertEqual((got, err), (0, ''), (kind, encoding))
                self.assertEqual(data, (prefix + said.replace('<out>', out)).encode(encoding, 'backslashreplace'),
                                 (kind, encoding))

