    def test_say_probes_a_stream_that_wrote_the_first_character_of_an_inputs_file_name(self):
        """form and same on a build's file whose name begins with '한' — and with 'ｱ' —, given by that name from its
        folder, so that the command's own lines begin with that character; stdout a stream over a file in
        iso2022_jp_2 — in iso2022_jp_ext —, errors 'backslashreplace', that character written and flushed, its bytes
        in the file, the encoder left in that character's set. Over a native buffered writer: the file's bytes one
        stream's — the character and the command's lines as one encoder writes them, not the lines encoded afresh
        after it —, exit 0, stderr empty. Over a raw file — no buffer holding the account of what its encoder
        writes —: exit 2, one stop naming the layer, the file as it stood (RP-P26's F3: PRIOR without its '한', and
        without its 'ｱ', each passed the whole suite — the stream then taken as stateless, the lines encoded afresh
        after what it wrote, and over the raw layer no stop; a command's own lines begin with an input's file name,
        which no alphabet bounds)."""
        fx = Fixture(self.tmp)
        cwd = os.getcwd()
        os.chdir(self.tmp)
        try:
            for encoding, first in (('iso2022_jp_2', '한'), ('iso2022_jp_ext', 'ｱ')):
                name = first + '.json'
                self.dump(name, fx.outputs())
                for kind in ('form', 'same'):
                    got0, err0, said, _ = self.native(fx, kind, name, io.StringIO(), 'plain')
                    self.assertEqual((got0, err0, said[:len(name)]), (0, '', name), (kind, encoding))
                    p = self.path(f'named-{kind}-{encoding}.txt')
                    with open(p, 'w', encoding=encoding, errors='backslashreplace') as f:
                        f.write(first)
                        f.flush()
                        with open(p, 'rb') as g:
                            wrote = g.read()
                        got, err, _, _ = self.native(fx, kind, name, f, encoding)
                    with open(p, 'rb') as g:
                        data = g.read()
                    want = (first + said).encode(encoding, 'backslashreplace')
                    self.assertEqual((got, err, data), (0, '', want), (kind, encoding))
                    self.assertTrue(wrote and want.startswith(wrote), (kind, encoding))
                    self.assertNotEqual(want, wrote + said.encode(encoding, 'backslashreplace'), (kind, encoding))
                    p = self.path(f'named-{kind}-{encoding}-raw.txt')
                    f = io.TextIOWrapper(io.FileIO(p, 'w'), encoding=encoding, errors='backslashreplace',
                                         write_through=True)
                    try:
                        f.write(first)
                        got, err, _, _ = self.native(fx, kind, name, f, encoding + '-raw')
                    finally:
                        f.close()
                    stop = (f'STOP: its own lines could not be written to stdout (OSError: its encoding {encoding} '
                            'marks its start or carries a state, and its binary layer — FileIO — cannot hold the '
                            'account of every byte its encoder writes)')
                    with open(p, 'rb') as g:
                        self.assertEqual((got, err, g.read()), (2, stop + '\n', wrote), (kind, encoding))
        finally:
            os.chdir(cwd)

    def test_a_stdout_over_a_subclass_of_a_native_buffered_writer_stops_each_command(self):
        """Each command — form, same, a1 and table, table on a synthetic build — run by main, stdout a stream in
        utf-16 whose binary layer is a subclass of a native buffered writer — of BufferedWriter, and of
        BufferedRandom — whose write takes the bytes and passes none on, over a raw file: exit 2 and one stop naming
        the layer by its class, for a1 and table their outputs named as left, no byte in the file (RP-P26's F4: the
        layer's test by isinstance in place of its exact type passed the whole suite — the subclass admitted, the
        run saying success with none of its lines delivered)."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for base, mode in ((io.BufferedWriter, 'w'), (io.BufferedRandom, 'w+')):
            class Sink(base):
                def write(self, data):
                    return len(data)
            for kind in ('form', 'same', 'a1', 'table'):
                tag = f'sink-{base.__name__}'
                p = self.path(f'{tag}-{kind}.txt')
                f = io.TextIOWrapper(Sink(io.FileIO(p, mode)), encoding='utf-16', errors='backslashreplace')
                try:
                    got, err, _, out = self.native(fx, kind, ok, f, tag)
                finally:
                    f.close()
                stop = ('STOP: its own lines could not be written to stdout (OSError: its encoding utf-16 marks its '
                        'start or carries a state, and its binary layer — Sink — cannot hold the account of every byte '
                        'its encoder writes)')
                if kind in ('a1', 'table'):
                    left = ['<out>'] + ([f'<out>/{n}' for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                        if kind == 'table' else [])
                    stop += f' after writing <out> — {HELD}' + '; '.join(left)
                self.assertEqual((got, err, os.path.getsize(p)), (2, stop + '\n', 0), (kind, base.__name__))

    def streams(self, fx, mode, argv, unbuffered=False, stdout='gone', stderr='pipe', env=None):
        """The tool run by STREAMS as a process of its own, stdin the null device, in mode — close1, close2, preload,
        exhaust-say, exhaust-tell, fault-before, fault-after, shut1, shut2, shut-fault <before|after> <say|tell>,
        stderr-none — sys.stderr None —, devnull-raises — os.open raising a RuntimeError where quiet opens the
        null device, before its effect —, del-stdout, del-stderr — the stream deleted from sys —, none-stdout —
        sys.stdout None —, raises <stdout|stderr> <raises|none|text> — the stream an object over the real one whose
        write puts the first half of its text into it and then raises RuntimeError, its fileno raising RuntimeError,
        raising io's UnsupportedOperation, or returning a str —, fault-stdout — sys.stdout an object with no descriptor
        of its own whose write puts half its text into the real one and then raises an ordinary exception whose message
        raises when it is rendered —, odd-close and odd-closed — sys.stdout an object with no descriptor of its own
        whose write fails with a broken pipe and whose close, or whose closed state, raises an ordinary exception of its
        own —, flush-fails <stdout|stderr> — the stream an object over the real one, its descriptor the real one's,
        whose flush raises every time, stdout None where it is stderr —, eq-raises <stdout|stderr> <marker> — the
        stream an object whose fileno returns an object whose equality raises, its write failing where it is
        stderr and stdout then None, the descriptors the run leaves open counted into the marker —, big-fileno
        <stdout|stderr> <number> <marker> — the same, its fileno returning the number, an int —, typed-fileno
        <stdout|stderr> <true|false|sub> <marker> — the stream an object whose fileno returns True, False or an
        instance of a subclass of int that carries the real stream's number, its flush raising where it is
        stdout, its write failing, stdout None where it is stderr, descriptor 0 a pipe's reading end, the
        descriptors the run leaves open, and those of 0, 1 and 2 it leaves at the null device, counted into the
        marker —, flush-closed
        <stdout|stderr> <marker> — the stream an object over the real one whose flush raises every time, its write,
        fileno, close and closed state the real one's, the real descriptor closed before the run, stdout None where it
        is stderr, the descriptors open after the run against those before the real one was closed counted into the
        marker —, stderr-takes
        <whole|one|zero|none> — sys.stderr an
        object over the real stderr
        whose writes put into it the whole text, its first character with the real write's count, nothing with a count
        of 0, or its first character with no count, its flush and its descriptor the real stderr's — or plain; stdout
        a pipe whose reader has gone, a pipe read whole, or full — a pipe whose writing end is nonblocking and filled,
        its reader open and not drained until the run ends —; stderr a pipe read whole, or one whose reader has gone;
        the environment env where one is given, the suite's own otherwise: (the exit; stderr's text, or None)."""
        cmd = [sys.executable, '-I', '-B'] + (['-u'] if unbuffered else []) + \
            ['-c', STREAMS, os.path.join(HERE, 'compare.py'), json.dumps(fx.pins), fx.msha, mode] + list(argv)
        ends, readers = {}, []
        for which, how in (('stdout', stdout), ('stderr', stderr)):
            if how in ('gone', 'full'):
                r, w = os.pipe()
                ends[which] = w
                if how == 'gone':
                    os.close(r)
                    continue
                readers.append(r)
                os.set_blocking(w, False)
                for size in (65536, 4096, 512, 1):
                    try:
                        while True:
                            os.write(w, b'p' * size)
                    except BlockingIOError:
                        pass
        try:
            p = subprocess.run(cmd, stdin=subprocess.DEVNULL, stdout=ends.get('stdout', subprocess.PIPE),
                               stderr=ends.get('stderr', subprocess.PIPE), timeout=600, env=env)
        finally:
            for fd in list(ends.values()) + readers:
                os.close(fd)
        return p.returncode, None if p.stderr is None else p.stderr.decode('utf-8')

    def test_the_stream_is_left_with_nothing_for_the_exits_flush_with_real_streams_and_descriptors(self):
        """The tool run as a process of its own, each command — table on a synthetic build —: descriptor 1 closed under
        a live stdout; the descriptors exhausted at say's entry, stdout's reader gone; stdout's buffer holding a byte,
        its reader gone; a pipe whose writing end is nonblocking and full, under -u and buffered: exit 2, stderr one
        stop naming the failure and, for table and a1, their outputs as left, nothing more — nothing left for the
        interpreter's own flush at exit to fail on; descriptor 2 closed, or the descriptors exhausted at tell's entry
        with stderr's reader gone, and an input that is absent: exit 2, nothing written."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        absent = self.path('absent.json')
        made = []

        def argv(kind, src):
            made.append(kind)
            out = self.path(f'streams-{kind}-{len(made)}' + ('.json' if kind == 'a1' else ''))
            return out, {'form': ['form', src], 'same': ['same', src, src],
                         'a1': ['a1', self.tmp if src == ok else self.path('absent-folder'), fx.manifest, out],
                         'table': ['table', self.tmp, fx.manifest, out, '--build', 'b', src]}[kind]
        ebadf = f'OSError: [Errno {errno.EBADF}] {os.strerror(errno.EBADF)}'
        eagain = f'BlockingIOError: [Errno {errno.EAGAIN}] {os.strerror(errno.EAGAIN)}'
        for mode, unbuffered, stdout, why in (('close1', False, 'pipe', ebadf), ('exhaust-say', False, 'gone', EPIPE),
                                              ('preload', False, 'gone', EPIPE), ('plain', True, 'full', eagain),
                                              ('plain', False, 'full', eagain)):
            for kind in ('form', 'same', 'a1', 'table'):
                out, av = argv(kind, ok)
                got, err = self.streams(fx, mode, av, unbuffered, stdout=stdout)
                stop = f'STOP: its own lines could not be written to stdout ({why})'
                if kind in ('a1', 'table'):
                    left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                    if kind == 'table' else [])
                    stop += f' after writing {out} — {HELD}' + '; '.join(left)
                    self.assertTrue(all(os.path.isfile(x) for x in (left if kind == 'a1' else left[1:])), (mode, kind))
                self.assertEqual((got, err), (2, stop + '\n'), (mode, unbuffered, stdout, kind))
        for mode, stderr in (('close2', 'pipe'), ('exhaust-tell', 'gone')):
            for kind in ('form', 'same', 'a1', 'table'):
                out, av = argv(kind, absent)
                got, err = self.streams(fx, mode, av, stdout='pipe', stderr=stderr)
                self.assertEqual((got, err if err is None else len(err), os.path.lexists(out)),
                                 (2, None if stderr == 'gone' else 0, False), (mode, kind))

