        """The tool run as a process of its own, each command — table on a synthetic build —, os.open raising a
        RuntimeError where quiet opens the null device, before its effect: stdout a pipe whose reader has gone — exit
        2, stderr one stop naming the stream's failure and, for table and a1, their outputs as left, nothing more —;
        stderr a pipe whose reader has gone and an input that is absent — exit 2, not 120, nothing written."""
