    def test_a_close_of_quiets_own_that_fails_is_caught_returned_and_named(self):
        """os.close failing when quiet calls it — before the descriptor is released, or after —: quiet raises nothing
        and returns the failure's text, the null device's descriptor left open only where the close failed before
        releasing it; None where nothing failed; say's Stop names that failure beside the stream's; tell, its stderr a
        pipe whose reader has gone, raises nothing."""
        real_close = os.close

        def live():
            out = set()
            for fd in range(1024):
                try:
                    os.fstat(fd)
                    out.add(fd)
                except OSError:
                    pass
            return out

        def failing(when):
            def close(fd):
                if sys._getframe(1).f_code is C.quiet.__code__:
                    if when == 'before':
                        raise OSError(errno.EIO, 'injected: the close in quiet, before the real close')
                    real_close(fd)
                    raise OSError(errno.EINTR, 'injected: the close in quiet, after the real close')
                return real_close(fd)
            return close

        def gone():
            r, w = os.pipe()
            os.close(r)
            return open(w, 'w', encoding='utf-8')
        with open(self.path('quiet-none.txt'), 'w') as f:
            self.assertIsNone(C.quiet(f))
        self.assertIsNone(C.quiet(io.StringIO()))
        for when, kind, code in (('before', 'OSError', errno.EIO), ('after', 'InterruptedError', errno.EINTR)):
            closed = (f"the null device's descriptor could not be closed ({kind}: [Errno {code}] injected: the close in "
                      f'quiet, {when} the real close)')
            with open(self.path(f'quiet-{when}.txt'), 'w') as f:
                before = live()
                with mock.patch.object(C.os, 'close', failing(when)):
                    got = C.quiet(f)
                extra = live() - before
                for fd in extra:
                    os.close(fd)
            self.assertEqual((got, len(extra)), (closed, 1 if when == 'before' else 0), when)
            s = gone()
            before = live()
            try:
                with mock.patch.object(sys, 'stdout', s), mock.patch.object(C.os, 'close', failing(when)), \
                        self.assertRaises(C.Stop) as cm:
                    C.say(['a line'])
            finally:
                for fd in live() - before:
                    os.close(fd)
                s.close()
            self.assertEqual(str(cm.exception), f'its own lines could not be written to stdout ({EPIPE}) — {closed}', when)
            s = gone()
            before = live()
            try:
                with mock.patch.object(sys, 'stderr', s), mock.patch.object(C.os, 'close', failing(when)):
                    self.assertIsNone(C.tell('STOP: a line'), when)
            finally:
                for fd in live() - before:
                    os.close(fd)
                s.close()

    def test_a_close_of_quiets_own_that_raises_another_class_is_caught_returned_and_named(self):
        """os.close raising a RuntimeError when quiet closes the null device's descriptor — before the descriptor is
        released, or after it —: quiet raises nothing and returns the failure's text, its class and its message; the
        null device's descriptor left open only where the close failed before releasing it."""
        real_close = os.close

        def live():
            out = set()
            for fd in range(1024):
                try:
                    os.fstat(fd)
                    out.add(fd)
                except OSError:
                    pass
            return out

        for when in ('before', 'after'):
            def close(fd, when=when):
                if sys._getframe(1).f_code is C.quiet.__code__:
                    if when == 'after':
                        real_close(fd)
                    raise RuntimeError(f'injected: the close in quiet, {when} the real close')
                return real_close(fd)
            with open(self.path(f'quiet-rt-{when}.txt'), 'w') as f:
                before = live()
                with mock.patch.object(C.os, 'close', close):
                    got = C.quiet(f)
                extra = live() - before
                for fd in extra:
                    os.close(fd)
            self.assertEqual((got, len(extra)), (f"the null device's descriptor could not be closed (RuntimeError: "
                                                 f'injected: the close in quiet, {when} the real close)',
                                                 1 if when == 'before' else 0), when)

    def test_a_write_of_no_byte_to_a_file_stops_the_run_and_removes_what_was_made(self):
        """os.write writing no byte when the file writer calls it, table and a1: exit 2, one stop naming the write and
        the bytes left, nothing left — one such write each; a writer that went on would meet the injected bound."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        real_write, zeros = os.write, []

        def write(fd, data):
            if sys._getframe(1).f_code is not C.put.__code__ or not len(data):
                return real_write(fd, data)
            zeros.append(len(data))
            if len(zeros) > 1000:
                raise OSError('injected: the file writer went on after 1000 writes of no byte')
            return 0
        self.table(fx, [('b', ok)], out='ref')
        sizes = {'table': os.path.getsize(self.path('ref', 'table.tsv')),
                 'a1': len((json.dumps(C.a1_object(fx.oracle()[0]), indent=2, allow_nan=False) + '\n').encode('utf-8'))}
        for kind in ('table', 'a1'):
            zeros.clear()
            out = self.path(f'zero-{kind}' + ('.json' if kind == 'a1' else ''))
            got, err = self.cli(fx, self.argv(fx, kind, out, ok), write=write)
            self.assertEqual((got, err, zeros, os.path.lexists(out)),
                             (2, f'STOP: writing {out} failed (OSError: a write to the file wrote no byte, {sizes[kind]} B '
                                 f'left) — nothing it wrote is left\n', [sizes[kind]], False), kind)

