    def test_a_thing_the_run_made_is_known_by_its_device_and_its_inode_both(self):
        """own and at_path, and undo through them, on a file whose inode is the run's own but whose device is not:
        another's — not removed, named —, as one whose inode differs; its own device and inode: the run's."""
        p = self.path('known.txt')
        with open(p, 'w') as f:
            f.write('x')
        st = os.stat(p)
        dfd = os.open(self.tmp, os.O_RDONLY | os.O_DIRECTORY)
        try:
            for ident, mine in (((st.st_dev, st.st_ino), True), ((st.st_dev + 1, st.st_ino), False),
                                ((st.st_dev, st.st_ino + 1), False)):
                self.assertEqual(C.own(dfd, 'known.txt', ident), mine, ident)
                if mine:
                    C.at_path(p, ident, 'file')
                else:
                    with self.assertRaises(OSError):
                        C.at_path(p, ident, 'file')
            m = C.Made(dfd, 'known.txt', p, 'file')
            m.fd, m.ident = os.open(p, os.O_RDONLY), (st.st_dev + 1, st.st_ino)
            try:
                self.assertEqual(C.undo([m]), f"left: {p} — another's in its place, not removed; the run's own not found "
                                              f'there')
            finally:
                os.close(m.fd)
            self.assertTrue(os.path.isfile(p))
        finally:
            os.close(dfd)

