    def test_a_write_of_no_byte_to_a_file_with_a_real_sigint_stops_and_passes_the_signal_on(self):
        """The tool run as a process of its own, os.write writing no byte when the file writer calls it, a real SIGINT
        sent once that write is reached, table — a synthetic build — and a1: under Python's default handler, the stop
        said once naming the write and the interrupt, nothing left, KeyboardInterrupt raised after it; under a handler
        set before the run, exit 2, the stop said once naming the write, nothing left, the signal passed on to that
        handler as the hold ends — one write of no byte in each."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        self.table(fx, [('b', ok)], out='ref')
        sizes = {'table': os.path.getsize(self.path('ref', 'table.tsv')),
                 'a1': len((json.dumps(C.a1_object(fx.oracle()[0]), indent=2, allow_nan=False) + '\n').encode('utf-8'))}
        for how, code, calls, tail in (('default', 'KeyboardInterrupt', 0, ' — interrupted before the stop was said'),
                                       ('own', '2', 1, '')):
            for kind in ('table', 'a1'):
                out = self.path(f'zero-{how}-{kind}' + ('.json' if kind == 'a1' else ''))
                marker = self.path(f'zero-{how}-{kind}.entered')
                cmd = [sys.executable, '-I', '-B', '-c', STREAMS, os.path.join(HERE, 'compare.py'), json.dumps(fx.pins),
                       fx.msha, f'put-zero {how} {marker}'] + self.argv(fx, kind, out, ok)
                p = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                try:
                    end = time.monotonic() + 120
                    while not os.path.exists(marker) and p.poll() is None and time.monotonic() < end:
                        time.sleep(0.01)
                    entered = os.path.exists(marker)
                    if entered and p.poll() is None:
                        os.kill(p.pid, signal.SIGINT)
                    so, se = p.communicate(timeout=120)
                finally:
                    if p.poll() is None:
                        p.kill()
                        p.communicate()
                stop = (f'STOP: writing {out} failed (OSError: a write to the file wrote no byte, {sizes[kind]} B left) — '
                        f'nothing it wrote is left{tail}\n')
                self.assertEqual((entered, p.returncode, so.decode('utf-8').splitlines()[-1:], se.decode('utf-8'),
                                  os.path.lexists(out)),
                                 (True, 0, [f'{code} · 1 write(s) of no byte · the handler before the run called {calls} '
                                            f'time(s)'], stop, False), (how, kind))

    def through(self, fx, argv, stream, handler=None):
        """The tool's command line on the fixture — its pins and manifest digest set for the run —, stdout the stream
        given, SIGINT's handler set before the run where one is given and restored after it: (the exit, or the name of
        what it raised; what it said on stderr)."""
        err = io.StringIO()
        old = signal.getsignal(signal.SIGINT)
        try:
            if handler is not None:
                signal.signal(signal.SIGINT, handler)
            with mock.patch.object(C, 'PINS', fx.pins), mock.patch.object(C, 'MANIFEST_SHA256', fx.msha), \
                    mock.patch.object(sys, 'stdout', stream), contextlib.redirect_stderr(err):
                try:
                    got = C.main(argv)
                except BaseException as e:
                    got = type(e).__name__
        finally:
            signal.signal(signal.SIGINT, old)
        return got, err.getvalue()

    def test_a_stdout_with_no_descriptor_has_every_character_it_takes_counted(self):
        """say, stdout a StringIO — no descriptor of its own — whose writes take what Takes is told: one character a
        write carried on, the lines whole; none, or a count that is not one of what it was given — None, True, -1, more
        than given —, a Stop naming it, the stream closed. Each command through main — table on a synthetic build —:
        one character a write, exit 0, the lines whole; none, exit 2, one stop naming the write and, for table and a1,
        their outputs as left, written whole, the stream closed."""
        lines = ['a · b', 'second line']
        s = Takes('one')
        with mock.patch.object(sys, 'stdout', s):
            C.say(lines)
        self.assertEqual((s.getvalue(), s.n), ('a · b\nsecond line\n', 18))
        for how, why in (('zero', 'took no character, 6 characters left'),
                         ('none', 'returned no count of what it was given: None'),
                         ('true', 'returned no count of what it was given: True'),
                         ('minus', 'returned no count of what it was given: -1'),
                         ('more', 'returned no count of what it was given: 7')):
            s = Takes(how)
            with mock.patch.object(sys, 'stdout', s), self.assertRaises(C.Stop) as cm:
                C.say(lines)
            self.assertEqual((str(cm.exception), s.closed),
                             (f'its own lines could not be written to stdout (OSError: a write to the stream {why})', True),
                             how)
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        made = []

        def argv(kind):
            made.append(kind)
            out = self.path(f'takes-{kind}-{len(made)}' + ('.json' if kind == 'a1' else ''))
            return out, {'form': ['form', ok], 'same': ['same', ok, ok], 'a1': ['a1', self.tmp, fx.manifest, out],
                         'table': ['table', self.tmp, fx.manifest, out, '--build', 'b', ok]}[kind]
        for kind in ('form', 'same', 'a1', 'table'):
            out0, av = argv(kind)
            s = Takes()
            self.assertEqual(self.through(fx, av, s), (0, ''), kind)
            said = s.getvalue()
            out1, av = argv(kind)
            s = Takes('one')
            self.assertEqual((self.through(fx, av, s), s.getvalue()), ((0, ''), said.replace(out0, out1)), kind)
            out2, av = argv(kind)
            s = Takes('zero')
            got, err = self.through(fx, av, s)
            stop = (f'STOP: its own lines could not be written to stdout (OSError: a write to the stream took no '
                    f'character, {len(said.split(chr(10))[0]) + 1} characters left)')
            if kind in ('a1', 'table'):
                left = [out2] + ([os.path.join(out2, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                 if kind == 'table' else [])
                stop += f' after writing {out2} — {HELD}' + '; '.join(left)
                self.assertTrue(all(os.path.isfile(x) for x in (left if kind == 'a1' else left[1:])), kind)
            self.assertEqual((got, err, s.closed), (2, stop + '\n', True), kind)

    def test_a_write_that_takes_no_character_with_a_real_sigint_is_named_and_the_signal_passed_on(self):
        """table — a synthetic build — and a1, stdout a StringIO whose writes take no character, a real SIGINT sent as
        the first is made: under Python's default handler the stop said once naming the write and the interrupt, the
        outputs as left, KeyboardInterrupt after it; under a handler set before the run, exit 2, the stop said once
        naming the write, the outputs as left, the signal passed on to that handler once as the hold ends; the stream
        closed, one write made."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        calls = []
        for how, handler, code, tail in (('default', None, 'KeyboardInterrupt', ' — interrupted before the stop was said'),
                                         ('own', lambda signum, frame: calls.append(signum), 2, '')):
            for kind in ('a1', 'table'):
                calls.clear()
                ref = self.path(f'takes-ref-{how}-{kind}' + ('.json' if kind == 'a1' else ''))
                s = Takes()
