    def test_an_input_ranges_role_and_selection_are_held_to_its_row(self):
        """A synthetic manifest, re-pinned, whose input maturity range's row says another role — output — or another
        selection — all —, its count and digest right: a1 stops at that range, its stop naming the row's role and
        selection, before any file is made."""
        fx = Fixture(self.tmp)
        with open(fx.manifest, encoding='utf-8') as f:
            lines = f.read().split('\n')
        i = next(k for k, l in enumerate(lines)
                 if ' · input · ' in l and not l.endswith('a row the tool does not read'))
        for field, new, says in ((1, 'output', 'output/const'), (4, 'all', 'input/all')):
            parts = lines[i].split(' · ')
            parts[field] = new
            bad = self.path(f'MANIFEST-input-{new}.md')
            with open(bad, 'w', encoding='utf-8') as f:
                f.write('\n'.join(lines[:i] + [' · '.join(parts)] + lines[i + 1:]))
            out = self.path(f'input-{new}.json')
            why = f"{parts[2]} {parts[3]}: the manifest's row is {says}, not input/const"
            with self.assertRaisesRegex(C.Stop, '^' + re.escape(why) + '$'):
                quiet(C.cmd_a1, self.tmp, bad, out, fx.pins, sha(bad))
            self.assertFalse(os.path.lexists(out), new)

    def test_a_range_whose_row_is_given_twice_stops_input_or_output(self):
        """A synthetic manifest, re-pinned, that gives a range's row twice — the input maturity range's, or E2's
        'RCS'!K11:K19 output range's —: a1 stops at that range, its stop naming two rows, before any file is made."""
        fx = Fixture(self.tmp)
        with open(fx.manifest, encoding='utf-8') as f:
            lines = f.read().split('\n')
        rows = (('input', next(k for k, l in enumerate(lines)
                               if ' · input · ' in l and not l.endswith('a row the tool does not read'))),
                ('output', next(k for k, l in enumerate(lines) if ' · E2 · ' in l and "'RCS'!K11:K19" in l)))
        for which, i in rows:
            parts = lines[i].split(' · ')
            bad = self.path(f'MANIFEST-twice-{which}.md')
            with open(bad, 'w', encoding='utf-8') as f:
                f.write('\n'.join(lines[:i + 1] + [lines[i]] + lines[i + 1:]))
            out = self.path(f'twice-{which}.json')
            why = f'{parts[2]} {parts[3]}: 2 rows in the manifest, not one'
            with self.assertRaisesRegex(C.Stop, '^' + re.escape(why) + '$'):
                quiet(C.cmd_a1, self.tmp, bad, out, fx.pins, sha(bad))
            self.assertFalse(os.path.lexists(out), which)

