    def test_a_standard_stream_deleted_from_sys_is_taken_as_none(self):
        """In the run itself, say with stdout deleted from sys raises its stop alone — stdout not open — and tell with
        stderr deleted raises nothing, each reading its stream once. The tool run as a process of its own, a standard
        stream deleted from sys before the run, or set to None — main's parser building puts a deleted stdout back as
        None before say reads it. stderr deleted, each command at an absent input — form's file, same's, a1's
        workbooks, table's build —: exit 2, nothing raised, nothing said, nothing made; a1 and table after their work —
        a synthetic build —, stdout a pipe whose reader has gone: exit 2, nothing raised, nothing said, their outputs
        left whole — the bytes a run with every stream in place writes. stdout deleted, and None, each command — form
        and same on a synthetic build, a1 and table —: exit 2, one stop on stderr naming stdout as not open, for table
        and a1 their outputs named as left and left whole; deleted and None the same."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        absent = self.path('absent.json')
        ref = {'a1': self.path('ref-a1.json'), 'table': self.path('ref-table')}
        quiet(C.cmd_a1, self.tmp, fx.manifest, ref['a1'], fx.pins, fx.msha)
        quiet(C.cmd_table, self.tmp, fx.manifest, ref['table'], [('b', ok)], [], fx.pins, fx.msha)
        names = ['cases.tsv', 'divergences.tsv', 'table.tsv']

        def whole(kind, out):
            if kind == 'a1':
                return os.path.isfile(out) and sha(out) == sha(ref['a1'])
            return os.path.isdir(out) and sorted(os.listdir(out)) == names and \
                all(sha(os.path.join(out, n)) == sha(os.path.join(ref['table'], n)) for n in names)
        real = sys.stdout, sys.stderr
        try:
            del sys.stdout
            with self.assertRaisesRegex(C.Stop, r'^its own lines could not be written to stdout \(OSError: stdout is '
                                                r'not open\)$'):
                C.say(['a line'])
            sys.stdout = real[0]
            del sys.stderr
            self.assertIsNone(C.tell('STOP: a stop · its line'))
        finally:
            sys.stdout, sys.stderr = real
        for kind in ('form', 'same', 'a1', 'table'):
            out = self.path(f'del-{kind}' + ('.json' if kind == 'a1' else ''))
            av = {'form': ['form', absent], 'same': ['same', absent, absent],
                  'a1': ['a1', self.path('absent-folder'), fx.manifest, out],
                  'table': ['table', self.tmp, fx.manifest, out, '--build', 'b', absent]}[kind]
            got, err = self.streams(fx, 'del-stderr', av, stdout='pipe')
            self.assertEqual((got, err, os.path.lexists(out)), (2, '', False), kind)
        for kind in ('a1', 'table'):
            out = self.path(f'del-done-{kind}' + ('.json' if kind == 'a1' else ''))
            got, err = self.streams(fx, 'del-stderr', self.argv(fx, kind, out, ok), stdout='gone')
            self.assertEqual((got, err, whole(kind, out)), (2, '', True), kind)
        said = {}
        why = 'STOP: its own lines could not be written to stdout (OSError: stdout is not open)'
        for mode in ('del-stdout', 'none-stdout'):
            for kind in ('form', 'same', 'a1', 'table'):
                out = self.path(f'{mode}-{kind}' + ('.json' if kind == 'a1' else ''))
                av = {'form': ['form', ok], 'same': ['same', ok, ok]}.get(kind) or self.argv(fx, kind, out, ok)
                got, err = self.streams(fx, mode, av, stdout='pipe')
                said[(mode, kind)] = (got, err.replace(out, '<out>'))
                self.assertTrue(err.startswith(why) and err.count('\n') == 1 and err.endswith('\n'), (mode, kind, err))
                if kind in ('a1', 'table'):
                    self.assertIn(f'after writing <out> — {HELD}', said[(mode, kind)][1], (mode, kind))
                    self.assertTrue(whole(kind, out), (mode, kind))
                self.assertEqual(got, 2, (mode, kind))
        self.assertEqual({k: v for (m, k), v in said.items() if m == 'del-stdout'},
                         {k: v for (m, k), v in said.items() if m == 'none-stdout'})

    def test_an_official_value_that_is_no_finite_number_and_a_maturity_that_is_a_boolean_stop(self):
        """Synthetic workbooks, the pins and the ranges' digests those of the bytes, whose E2 'RCS'!G11 — B1's w_gov —
        holds a number read as infinity, a text, or a formula without a cached value; and whose first maturity of
        E1's G25:G174 is a boolean, TRUE: a1 and table — a synthetic build — stop before any file, the stop naming
        the cell and its value."""
