    def test_form_names_a_curve_that_is_no_object_lacks_a_maturity_or_holds_a_key_beyond_them_on_each_curve(self):
        """A build with one of the four curves the brief's form names — A1's zero_rates_cc of 50 maturities, and A1's
        basic_rfr, A2's curve and A3's curve of 150 — changed alone: a number in the curve's place; its seventeenth
        maturity missing; a key beyond its maturities; a null at its seventeenth maturity: form says each by its own
        lines and counts exactly — one deviation naming the curve, the numbers the 535 less the curve's, less one, or
        whole; the null no deviation, counted beside the numbers, the form conforming (the sweep's S0698, S0700,
        S0702 and S0708 on revision 122's bytes: each of form's four guards of a curve kept for the 150-output curves
        alone passed the whole suite — no such specimen had met the curve of 50)."""
        fx = Fixture(self.tmp)
        for case, key, n in (('A1', 'zero_rates_cc', 50), ('A1', 'basic_rfr', 150), ('A2', 'curve', 150),
                             ('A3', 'curve', 150)):
            for name in ('number', 'missing', 'beyond', 'null'):
                o = fx.outputs()
                if name == 'number':
                    o[case][key] = 7
                    want = (1, [f'numbers where the form expects one: {535 - n} of 535',
                                f'deviation: {case}.{key}: a number, not an object of maturities',
                                'FORM: 1 deviation(s)', ''])
                elif name == 'missing':
                    del o[case][key]['17']
                    want = (1, ['numbers where the form expects one: 534 of 535',
                                f"deviation: {case}.{key}: maturities missing ['17']", 'FORM: 1 deviation(s)', ''])
                elif name == 'beyond':
                    o[case][key][str(n + 1)] = 0.5
                    want = (1, ['numbers where the form expects one: 535 of 535',
                                f"deviation: {case}.{key}: keys beyond maturities 1 to {n}: ['{n + 1}']",
                                'FORM: 1 deviation(s)', ''])
                else:
                    o[case][key]['17'] = None
                    want = (0, ['numbers where the form expects one: 534 of 535 · null — a result not computed, as '
                                'the brief permits: 1', 'FORM: conforming', ''])
                p = self.dump(f'{name}-{case}-{key}.json', o)
                r, log = quiet(C.cmd_form, p, False)
                self.assertEqual((r, log.split('\n')), (want[0], [
                    f"{p} · sha256 {sha(p)} · against the brief's form (item 1)"] + want[1]), (case, key, name))

    def test_form_holds_an_isolated_files_two_objects_to_every_guard_it_holds_a_returned_file_to(self):
        """One of an isolated file's two objects — A2, then A3 — changed alone, and the same change in a returned
        file: a key beyond the case's; a key beyond its curve's maturities; a maturity missing; a scalar missing; the
        curve missing; a null at a scalar and at a maturity; a string at a scalar and at a maturity; a number in the
        curve's place; a number in the case's place; the case missing. And the file itself: a number where its
        object is due, a byte-order mark before its JSON, bytes that do not parse. form says each by its own lines
        and counts exactly, in each mode — with --isolated against 307 numbers and its own first line, without it
        against 535 —, one deviation named in the same words, a null no deviation; and the table on that returned
        file and that isolated file names each input's form in one line, the same line in each of its three files'
        heads (RP-P27's F2: a curve's keys beyond its maturities, a case's keys beyond the brief's and a curve's
        missing maturities, each reported for the returned files alone, each passed the whole suite — no negative
        form had met the isolated mode)."""
        fx = Fixture(self.tmp)
        base = json.dumps(fx.outputs())

        def said(p, isolated, dev, lost, nulls):
            expected = 307 if isolated else 535
            numbers = 0 if lost is None else expected - lost
            ok = not dev and numbers + nulls == expected
            what = 'its A2 and A3 objects (the brief, item 3)' if isolated else "the brief's form (item 1)"
            lines = [f'{p} · sha256 {sha(p)} · against {what}',
                     f'numbers where the form expects one: {numbers} of {expected}'
                     + (f' · null — a result not computed, as the brief permits: {nulls}' if nulls else '')]
            lines += [f'deviation: {d}' for d in dev] + ['FORM: conforming' if ok else f'FORM: {len(dev)} deviation(s)']
            head = (f"# b {'isolated' if isolated else 'returned'}: sha256 {sha(p)} · form: "
                    + ('conforming' if ok else f'{len(dev)} deviation(s)') + f' · numbers {numbers} of {expected}'
                    + (f' · null, not computed: {nulls}' if nulls else ''))
            return (0 if ok else 1, lines + ['']), head

        def held(tag, pr, pi, dev, lost, nulls):
            heads = []
            for p, isolated in ((pr, False), (pi, True)):
                want, head = said(p, isolated, dev, lost, nulls)
                r, log = quiet(C.cmd_form, p, isolated)
                self.assertEqual((r, log.split('\n')), want, (tag, isolated))
                heads.append(head)
            _, files = self.table(fx, [('b', pr)], [('b', pi)], out='t-' + tag)
            for n in ('table.tsv', 'cases.tsv', 'divergences.tsv'):
                self.assertEqual([h for h in files[n][0] if h.startswith('# b ')], heads, (tag, n))

        def specimens(case, size):
            c = case + '.curve'
            return [
                ('beyond-case', lambda d: d[case].update(unrequested=0.5),
                 [f"{case}: keys beyond the brief's: ['unrequested']"], 0, 0),
                ('beyond-curve', lambda d: d[case]['curve'].update({'151': 0.5}),
                 [f"{c}: keys beyond maturities 1 to 150: ['151']"], 0, 0),
                ('maturity-missing', lambda d: d[case]['curve'].pop('17'), [f"{c}: maturities missing ['17']"], 1, 0),
                ('scalar-missing', lambda d: d[case].pop('llfr'), [f'{case}.llfr missing'], 1, 0),
                ('curve-missing', lambda d: d[case].pop('curve'), [f'{c} missing'], 150, 0),
                ('scalar-null', lambda d: d[case].update(llfr=None), [], 1, 1),
                ('maturity-null', lambda d: d[case]['curve'].update({'17': None}), [], 1, 1),
                ('scalar-string', lambda d: d[case].update(llfr='x'),
                 [f'{case}.llfr: non-numeric: a JSON string'], 1, 0),
                ('maturity-string', lambda d: d[case]['curve'].update({'17': 'x'}),
                 [f'{c}.17: non-numeric: a JSON string'], 1, 0),
                ('curve-number', lambda d: d[case].update(curve=7),
                 [f'{c}: a number, not an object of maturities'], 150, 0),
                ('case-number', lambda d: d.update({case: 7}), [f'{case}: a number, not an object'], size, 0),
                ('case-missing', lambda d: d.pop(case), [f'{case} missing'], size, 0)]

        for case, size in (('A2', 153), ('A3', 154)):
            for name, edit, dev, lost, nulls in specimens(case, size):
                tag, files = f'{name}-{case}', []
                for kind in ('returned', 'isolated'):
                    o = json.loads(base)
                    if kind == 'isolated':
                        o = {'A2': o['A2'], 'A3': o['A3']}
                    edit(o)
                    files.append(self.dump(f'{tag}-{kind}.json', o))
                held(tag, files[0], files[1], dev, lost, nulls)
        whole = json.loads(base)
        two = {'A2': whole['A2'], 'A3': whole['A3']}
        bom = b'\xef\xbb\xbf'
        for tag, make, dev, lost in (('no-object', lambda d: '7', ['the file is not a JSON object'], None),
                                     ('bom', lambda d: bom + json.dumps(d).encode('utf-8'),
                                      ['a UTF-8 byte-order mark before the JSON'], 0),
                                     ('no-json', lambda d: '{', None, None)):
            pr = self.dump(tag + '-returned.json', text=make(whole))
            pi = self.dump(tag + '-isolated.json', text=make(two))
            if dev is None:
                dev = [C.load(pi)[2]]
                self.assertTrue(dev[0].startswith('the file does not parse as JSON ('), dev)
            held(tag, pr, pi, dev, lost, 0)

    def test_an_isolated_files_other_keys_are_left_alone_and_a_returned_files_are_held(self):
        """The mode's one difference, held from both sides. An isolated file with its A2 and A3 objects whole and
        four keys beside them — an A1 that is a number, a whole B1, and two the brief does not name —: form
        --isolated conforming, 307 numbers of 307; the same file without --isolated held to the brief's whole form —
        the two keys beyond its six, A1 no object, B2 and C1 missing, 316 numbers of 535. A returned file with every
        declared output and the same two keys beside them: one deviation naming both, 535 of 535. The table on that
        returned file and that isolated file: each input's form in one line, the same in each of its three files'
        heads."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        iso = self.dump('iso.json', {'A1': 7, 'B1': o['B1'], 'Z9': 1, 'note': 'beside them', 'A2': o['A2'],
                                     'A3': o['A3']})
        ret = self.dump('ret.json', dict(o, Z9=1, note='beside them'))
        beyond = "deviation: keys beyond the brief's six: ['Z9', 'note']"
        r, log = quiet(C.cmd_form, iso, True)
        self.assertEqual((r, log.split('\n')), (0, [
            f'{iso} · sha256 {sha(iso)} · against its A2 and A3 objects (the brief, item 3)',
            'numbers where the form expects one: 307 of 307', 'FORM: conforming', '']))
        r, log = quiet(C.cmd_form, iso, False)
        self.assertEqual((r, log.split('\n')), (1, [
            f"{iso} · sha256 {sha(iso)} · against the brief's form (item 1)",
            'numbers where the form expects one: 316 of 535', beyond, 'deviation: A1: a number, not an object',
            'deviation: B2 missing', 'deviation: C1 missing', 'FORM: 4 deviation(s)', '']))
        r, log = quiet(C.cmd_form, ret, False)
        self.assertEqual((r, log.split('\n')), (1, [
            f"{ret} · sha256 {sha(ret)} · against the brief's form (item 1)",
            'numbers where the form expects one: 535 of 535', beyond, 'FORM: 1 deviation(s)', '']))
        _, files = self.table(fx, [('b', ret)], [('b', iso)])
        for n in ('table.tsv', 'cases.tsv', 'divergences.tsv'):
            self.assertEqual([h for h in files[n][0] if h.startswith('# b ')], [
                f'# b returned: sha256 {sha(ret)} · form: 1 deviation(s) · numbers 535 of 535',
                f'# b isolated: sha256 {sha(iso)} · form: conforming · numbers 307 of 307'], n)

