    def test_each_of_the_tables_three_files_heads_is_whole_and_in_order(self):
        """The table on two builds, b2 named first and a1x second, each with its isolated file, the isolated files
        given in the other order: each of its three files' heads the whole list, in order, and nothing else — the
        title; the tool's line with the sha256 of the tool's own file; the command by roles, as it was given; the
        workbooks at their pins; the manifest's line; each input's line, a build's returned file and then its
        isolated one, in the builds' order; the source line, the tool's constant, its words held here; the file's own
        line (RP-P26's F5: cases.tsv without the tool's line or without the inputs' lines, divergences.tsv without
        the command's, the source line misstated past its first words and the workbooks' line twice in table.tsv
        each passed the whole suite)."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        ok = self.dump('ok.json', o)
        iso = self.dump('iso.json', {'A2': o['A2'], 'A3': o['A3']})
        _, files = self.table(fx, [('b2', ok), ('a1x', ok)], [('a1x', iso), ('b2', iso)])
        common = [
            '# replicability test 01 - the pass-or-fail table (the preregistration, sections 5 and 6)',
            f'# tool: compare.py sha256 {sha(os.path.join(HERE, "compare.py"))}',
            '# command: compare.py table <workbooks> <manifest> <out> --build b2 <b2 returned> --build a1x '
            '<a1x returned> --isolated a1x <a1x isolated> --isolated b2 <b2 isolated> — every file and folder shown '
            'by its role, the files named by their sha256 below',
            '# workbooks: ' + ' · '.join(f'{w} {fx.pins[w]}' for w in ('E1', 'E2', 'E3')) + ' — each equal to its pin',
            f'# manifest: sha256 {fx.msha} — the frozen manifest; ranges held to its digests: 17 (14 outputs, '
            '3 maturities)',
            f'# b2 returned: sha256 {sha(ok)} · form: conforming · numbers 535 of 535',
            f'# b2 isolated: sha256 {sha(iso)} · form: conforming · numbers 307 of 307',
            f'# a1x returned: sha256 {sha(ok)} · form: conforming · numbers 535 of 535',
            f'# a1x isolated: sha256 {sha(iso)} · form: conforming · numbers 307 of 307',
            "# Source: EIOPA - European Insurance and Occupational Pensions Authority (the oracle: the workbooks' "
            'cached outputs, read and compared here, not reproduced)']
        own = {'table.tsv': 'one row per declared output; difference: |value - official|, exact, shown to three '
                            'significant digits, rounded half to even',
               'cases.tsv': 'a case passes for a build when every one of its declared outputs passes (section 5)',
               'divergences.tsv': 'every failing output of table.tsv, none chosen (section 6); each attributed on '
                                  'stated grounds, or left unresolved'}
        self.assertEqual('# ' + C.SOURCE, common[-1])
        for n in ('table.tsv', 'cases.tsv', 'divergences.tsv'):
            self.assertEqual(files[n][0], common + ['# ' + own[n]], n)

    def test_each_files_head_is_whole_and_in_order_for_one_build_and_for_two_with_no_isolated_file_one_or_each(self):
        """The table on one build and on two — b2 named first, a1x second —, with no isolated file, with one build's
        alone and with each build's, the isolated files given in the other order: each of its three files' heads
        the whole list, in order, and nothing else — the title; the tool's line with the sha256 of the tool's own
        file; the command by roles, as it was given; the workbooks at their pins; the manifest's line; each input's
        line, a build's returned file and then its isolated one where it has one, in the builds' order; the source
        line, its words held here; the file's own line (RP-P27's F4: cases.tsv's head without the tool's line where
        no isolated file is given passed the whole suite — the one test of the heads whole gave each build its
        isolated file)."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        ok = self.dump('ok.json', o)
        iso = self.dump('iso.json', {'A2': o['A2'], 'A3': o['A3']})
        two = [('b2', ok), ('a1x', ok)]
        scenes = [(two[:1], []), (two[:1], [('b2', iso)]), (two, []), (two, [('a1x', iso)]), (two, [('b2', iso)]),
                  (two, [('a1x', iso), ('b2', iso)])]
        own = {'table.tsv': 'one row per declared output; difference: |value - official|, exact, shown to three '
                            'significant digits, rounded half to even',
               'cases.tsv': 'a case passes for a build when every one of its declared outputs passes (section 5)',
               'divergences.tsv': 'every failing output of table.tsv, none chosen (section 6); each attributed on '
                                  'stated grounds, or left unresolved'}
        source = ("# Source: EIOPA - European Insurance and Occupational Pensions Authority (the oracle: the "
                  "workbooks' cached outputs, read and compared here, not reproduced)")
        self.assertEqual('# ' + C.SOURCE, source)
        for i, (builds, isolated) in enumerate(scenes):
            _, files = self.table(fx, builds, isolated, out=f'heads-{i}')
            given = [n for n, _ in isolated]
            command = ''.join(f' --build {n} <{n} returned>' for n, _ in builds) + \
                ''.join(f' --isolated {n} <{n} isolated>' for n in given)
            inputs = []
            for n, _ in builds:
                inputs.append(f'# {n} returned: sha256 {sha(ok)} · form: conforming · numbers 535 of 535')
                if n in given:
                    inputs.append(f'# {n} isolated: sha256 {sha(iso)} · form: conforming · numbers 307 of 307')
            common = [
                '# replicability test 01 - the pass-or-fail table (the preregistration, sections 5 and 6)',
                f'# tool: compare.py sha256 {sha(os.path.join(HERE, "compare.py"))}',
                f'# command: compare.py table <workbooks> <manifest> <out>{command} — every file and folder shown by '
                'its role, the files named by their sha256 below',
                '# workbooks: ' + ' · '.join(f'{w} {fx.pins[w]}' for w in ('E1', 'E2', 'E3'))
                + ' — each equal to its pin',
                f'# manifest: sha256 {fx.msha} — the frozen manifest; ranges held to its digests: 17 (14 outputs, '
                '3 maturities)'] + inputs + [source]
            self.assertEqual(len(common), 6 + len(builds) + len(isolated), i)
            for n in ('table.tsv', 'cases.tsv', 'divergences.tsv'):
                self.assertEqual(files[n][0], common + ['# ' + own[n]], (i, n))

    def test_each_builds_case_rows_and_console_lines_count_its_own_rows_of_the_table_alone(self):
        """Three builds whose results differ within the same cases — g, its every value the official; b1, A1's llfr
        off by 1; b2, A1's llfr and its basic_rfr at 7, A2's cssr and C1's rcs off by 1 — and two isolated files — one
        whole, one with A2's cssr, A3's llfr and A3's curve at 9 off by 1 —, the table run on two builds and then on
        three, in other orders, a build's isolated file failing where its returned file passes and passing where it
        fails: the failing rows of table.tsv where the edits put them and nowhere else; each build's case rows in
        cases.tsv — every column, in the builds' order, its returned file's and then its isolated file's — and its
        console lines, each counted from that build's own rows of that kind and case alone (RP-P28's F2: a case's
        failures counted across the builds of its kind and case passed the whole suite — the tests of several builds
        gave each build the same results, or held a case row's first four columns alone)."""
        fx = Fixture(self.tmp)
        o = fx.outputs()

        def edited(*where):
            e = json.loads(json.dumps(o))
            for case, key, m in where:
                if m is None:
                    e[case][key] += 1.0
                else:
                    e[case][key][str(m)] += 1.0
            return e

        g = self.dump('cases-g.json', o)
        b1 = self.dump('cases-b1.json', edited(('A1', 'llfr', None)))
        b2 = self.dump('cases-b2.json', edited(('A1', 'llfr', None), ('A1', 'basic_rfr', 7), ('A2', 'cssr', None),
                                               ('C1', 'rcs', None)))
        e = edited(('A2', 'cssr', None), ('A3', 'llfr', None), ('A3', 'curve', 9))
        whole = self.dump('cases-iso-whole.json', {'A2': o['A2'], 'A3': o['A3']})
        bad = self.dump('cases-iso-bad.json', {'A2': e['A2'], 'A3': e['A3']})
        scenes = [([('g', g), ('b1', b1)], []),
                  ([('b1', b1), ('g', g)], [('g', bad)]),
                  ([('b2', b2), ('g', g), ('b1', b1)], [('g', bad), ('b2', whole)])]
        known = {('g', 'returned'): {}, ('b1', 'returned'): {'A1': 1}, ('b2', 'returned'): {'A1': 2, 'A2': 1, 'C1': 1},
                 ('g', 'isolated'): {'A2': 1, 'A3': 2}, ('b2', 'isolated'): {}}
        size = {'A1': 201, 'A2': 153, 'A3': 154, 'B1': 9, 'B2': 9, 'C1': 9}
        for i, (builds, isolated) in enumerate(scenes):
            log, files = self.table(fx, builds, isolated, out=f'cases-{i}')
            rows = files['table.tsv'][2]
            given = dict(isolated)
            inputs = [(n, k) for n, _ in builds for k in ('returned', 'isolated') if k == 'returned' or n in given]
            self.assertEqual(sorted({(r[0], r[1]) for r in rows}), sorted(inputs), i)
            want = []
            for n, k in inputs:
                for case in C.CASES:
                    if k == 'isolated' and case not in ('A2', 'A3'):
                        continue
                    own = [r for r in rows if (r[0], r[1], r[2]) == (n, k, case)]
                    failed = known[(n, k)].get(case, 0)
                    self.assertEqual((len(own), sum(r[9] == 'FAIL' for r in own)), (size[case], failed),
                                     (i, n, k, case))
                    want.append([n, k, case, str(size[case]), str(size[case] - failed), str(failed),
                                 'FAIL' if failed else 'PASS'])
            self.assertEqual(files['cases.tsv'][1:],
                             (['build', 'kind', 'case', 'outputs', 'passed', 'failed', 'result'], want), i)
            self.assertEqual([l for l in log.split('\n') if ' outputs · ' in l],
                             [f'{c[0]} · {c[1]} · {c[2]} · {c[3]} outputs · {c[4]} pass · {c[5]} fail · {c[6]}'
                              for c in want], i)

    def test_two_builds_each_with_its_isolated_file_keep_their_order_and_their_own_cases(self):
        """Two builds, b2 named first and a1x second, each with its isolated file — b2's given by a path that is the
        word «returned», relative to the folder the run starts in —: the head lines and the rows in the order of the
        builds, each build's isolated file after its returned one; cases.tsv each build's own."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        ok = self.dump('ok.json', o)
        iso = {'A2': o['A2'], 'A3': o['A3']}
        iso_a = self.dump('iso-a.json', iso)
        self.dump('returned', iso)
        cwd = os.getcwd()
        os.chdir(self.tmp)
        try:
            _, files = self.table(fx, [('b2', ok), ('a1x', ok)], [('a1x', iso_a), ('b2', 'returned')])
        finally:
            os.chdir(cwd)
        head, _, rows = files['table.tsv']
        self.assertEqual([h.split(':')[0] for h in head if h.split(' ')[1] in ('b2', 'a1x')],
                         ['# b2 returned', '# b2 isolated', '# a1x returned', '# a1x isolated'])
        order = []
        for r in rows:
            if not order or order[-1] != (r[0], r[1]):
                order.append((r[0], r[1]))
        self.assertEqual(order, [('b2', 'returned'), ('b2', 'isolated'), ('a1x', 'returned'), ('a1x', 'isolated')])
        want = []
        for b in ('b2', 'a1x'):
            want += [[b, 'returned', c, n] for c, n in (('A1', '201'), ('A2', '153'), ('A3', '154'), ('B1', '9'),
                                                        ('B2', '9'), ('C1', '9'))]
            want += [[b, 'isolated', c, n] for c, n in (('A2', '153'), ('A3', '154'))]
        self.assertEqual([c[:4] for c in files['cases.tsv'][2]], want)

