    def test_a_builds_infinity_is_a_departure_and_fails_its_output_alone(self):
        """A build whose A1 llfr is Infinity and whose A2 cssr is -Infinity: form names both, exit 1; the table fails
        those two outputs alone, each naming its token, and passes the rest."""
        fx = Fixture(self.tmp)
        o = fx.outputs()
        o['A1']['llfr'], o['A2']['cssr'] = '@@INF@@', '@@NINF@@'
        p = self.dump('x.json', text=json.dumps(o, indent=1).replace('"@@INF@@"', 'Infinity')
                      .replace('"@@NINF@@"', '-Infinity'))
        r, log = quiet(C.cmd_form, p, False)
        self.assertEqual((r, [l for l in log.split('\n') if l.startswith('deviation: ')]), (1, [
            'deviation: A1.llfr: non-numeric: Infinity, not a JSON number',
            'deviation: A2.cssr: non-numeric: -Infinity, not a JSON number']))
        _, files = self.table(fx, [('b', p)])
        rows = files['table.tsv'][2]
        self.assertEqual([(r[2], r[3], r[10]) for r in rows if r[9] == 'FAIL'], [
            ('A1', 'llfr', 'non-numeric: Infinity, not a JSON number'),
            ('A2', 'cssr', 'non-numeric: -Infinity, not a JSON number')])
        self.assertEqual(sum(1 for r in rows if r[9] == 'PASS'), 533)

    def odd_stream(self, mode):
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for kind in ('a1', 'table'):
            out = self.path(f'{mode}-{kind}' + ('.json' if kind == 'a1' else ''))
            got, err = self.streams(fx, mode, self.argv(fx, kind, out, ok), stdout='pipe')
            left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                            if kind == 'table' else [])
            self.assertEqual((got, err), (2, f'STOP: its own lines could not be written to stdout (BrokenPipeError: '
                                             f'[Errno {errno.EPIPE}] injected: the reader has gone) after writing {out}'
                                             f' — {HELD}' + '; '.join(left) + '\n'), (mode, kind))
            self.assertTrue(os.path.isfile(out) if kind == 'a1' else os.path.isdir(out), (mode, kind))

    def test_a_stream_whose_close_raises_an_ordinary_exception_is_taken_from_the_exits_flush(self):
        """The tool run as a process of its own, stdout an object with no descriptor of its own whose write fails with
        a broken pipe and whose close raises an ordinary exception of its own: a1 and table — a synthetic build —:
        exit 2, one stop naming the stream's failure, their outputs named as left, written whole."""
        self.odd_stream('odd-close')

    def test_a_stream_whose_closed_state_raises_an_ordinary_exception_is_taken_from_the_exits_flush(self):
        """The tool run as a process of its own, stdout an object with no descriptor of its own whose write fails with
        a broken pipe and whose closed state raises an ordinary exception of its own: a1 and table — a synthetic
        build —: exit 2, one stop naming the stream's failure, their outputs named as left, written whole."""
