    def test_a_stream_failure_whose_message_raises_is_named_by_its_class(self):
        """The tool run as a process of its own, stdout an object with no descriptor of its own whose write puts half
        its text into the real stdout and then raises an ordinary exception whose message raises when it is rendered:
        each command — form and same on a synthetic build, a1 and table — exit 2, one stop naming the stream's failure
        by the exception's class alone, for table and a1 their outputs named as left, written whole."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for kind in ('form', 'same', 'a1', 'table'):
            out = self.path(f'fault-{kind}' + ('.json' if kind == 'a1' else ''))
            av = {'form': ['form', ok], 'same': ['same', ok, ok]}.get(kind) or self.argv(fx, kind, out, ok)
            got, err = self.streams(fx, 'fault-stdout', av, stdout='pipe')
            why = 'its own lines could not be written to stdout (Fault, its message not rendered)'
            if kind in ('a1', 'table'):
                left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                if kind == 'table' else [])
                why += f' after writing {out} — {HELD}' + '; '.join(left)
                self.assertTrue(os.path.isfile(out) if kind == 'a1' else os.path.isdir(out), kind)
            self.assertEqual((got, err), (2, f'STOP: {why}\n'), kind)

    def test_every_exception_the_tool_takes_and_names_is_rendered_inside_the_guard_that_took_it(self):
        """Each other place where the tool names an exception it took, given one whose message raises when it is
        rendered — an OSError without a reason where the place names its reason —: main's handler of an error the tool
        did not foresee and its handler of a stop or an OSError; quiet's close of its own; the closing's failures as
        the stop is composed; the writer's failure; the parent's opening; the new folder's making and its opening; the
        new file's making; and undo's four — an identity not read, a making under way not looked for, a removal failing
        after its effect, a thing not removed —: each named by the exception's class alone, nothing raised, exit 2
        where a command runs. The helper itself on a message that renders, on one that raises, and on a class whose own
        name cannot be read."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        nr = 'its message not rendered'

        def main_of(argv, target, fault):
            err = io.StringIO()
            with mock.patch.object(C, target, mock.Mock(side_effect=fault)), contextlib.redirect_stderr(err), \
                    contextlib.redirect_stdout(io.StringIO()):
                got = C.main(argv)
            return got, err.getvalue()
        self.assertEqual(main_of(['same', ok, ok], 'cmd_same', Fault('injected')),
                         (2, f'STOP: an error the tool did not foresee — Fault, {nr}\n'))
        self.assertEqual(main_of(['form', ok], 'read_bytes', FaultOS(errno.EIO, 'injected')),
                         (2, f'STOP: FaultOS, {nr}\n'))
        r, w = os.pipe()
        stream = os.fdopen(w, 'w')
        o_close = os.close

        def close(fd):
            o_close(fd)
            raise FaultOS(errno.EIO, 'injected')
        try:
            with mock.patch.object(C.os, 'close', close):
                said = C.quiet(stream)
        finally:
            stream.close()
            os.close(r)
        self.assertEqual(said, f"the null device's descriptor could not be closed (FaultOS, {nr})")
        self.assertEqual(C.stop_says('p', [], None, None, [FaultOS(errno.EIO, 'injected')], False),
                         f'p: written whole and checked at its path, but its descriptors not all closed (FaultOS, {nr})'
                         ' — no longer held, nothing removed; left: ')
        o_open, o_stat, o_unlink = os.open, os.stat, os.unlink

        def parent_open(path, flags, *a, **kw):
            if flags & os.O_DIRECTORY and kw.get('dir_fd') is None:
                raise FaultOS(errno.EACCES, 'injected')
            return o_open(path, flags, *a, **kw)

        def folder_open(path, flags, *a, **kw):
            if flags & os.O_DIRECTORY and kw.get('dir_fd') is not None:
                raise FaultOS()
            return o_open(path, flags, *a, **kw)

        def file_open(path, flags, *a, **kw):
            if flags & os.O_CREAT:
                raise FaultOS()
            return o_open(path, flags, *a, **kw)

        def mkdir(*a, **kw):
            raise FaultOS()

        def fstat(fd):
            raise FaultOS()

        def stat(path, *a, **kw):
            if kw.get('dir_fd') is not None:
                raise FaultOS()
            return o_stat(path, *a, **kw)

        def unlink_after(path, *a, **kw):
            o_unlink(path, *a, **kw)
            raise FaultOS()

        def unlink_before(path, *a, **kw):
            raise FaultOS()
        eio = f'OSError: [Errno {errno.EIO}] injected'
        for name, kind, fault, patches, why in (
                ('writer', 'a1', Fault('injected'), {}, f'writing @ failed (Fault, {nr}) — nothing it wrote is left'),
                ('parent', 'a1', None, {'open': parent_open}, f'@: its folder cannot be opened — FaultOS, {nr}'),
                ('folder-made', 'table', None, {'mkdir': mkdir},
                 f'writing @ failed (OSError: the new folder cannot be made — FaultOS, {nr}) — nothing it wrote is'
                 ' left'),
                ('folder-opened', 'table', None, {'open': folder_open},
                 f'writing @ failed (OSError: the new folder cannot be opened as the folder made — a link or another in'
                 f' its place (FaultOS, {nr})) — left: @ — not opened as the folder the run made: not removed'),
                ('file-made', 'a1', None, {'open': file_open},
                 f'writing @ failed (OSError: the new file cannot be made — FaultOS, {nr}) — nothing it wrote is left'),
                ('identity', 'a1', None, {'fstat': fstat},
                 f'writing @ failed (FaultOS, {nr}) — left: @ — made by the run, its identity not read (FaultOS, {nr}):'
                 ' not removed'),
                ('under-way', 'a1', None, {'open': file_open, 'stat': stat},
                 f'writing @ failed (OSError: the new file cannot be made — FaultOS, {nr}) — left: @ — its making under'
                 f' way, not looked for: FaultOS, {nr}'),
                ('removed-after', 'a1', OSError(errno.EIO, 'injected'), {'unlink': unlink_after},
                 f'writing @ failed ({eio}) — nothing it wrote is left — @ — removed, its removal failing after its'
                 f' effect: FaultOS, {nr}'),
                ('not-removed', 'a1', OSError(errno.EIO, 'injected'), {'unlink': unlink_before},
                 f'writing @ failed ({eio}) — left: @ — not removed: FaultOS, {nr}')):
            out = self.path(name + ('.json' if kind == 'a1' else ''))
            with contextlib.ExitStack() as st:
                if fault is not None:
                    st.enter_context(mock.patch.object(C, 'put', mock.Mock(side_effect=fault)))
                got, err = self.cli(fx, self.argv(fx, kind, out, ok), **patches)
            self.assertEqual((got, err), (2, 'STOP: ' + why.replace('@', out) + '\n'), name)
        self.assertEqual((C.rendered(ValueError('plain')), C.rendered(ValueError('plain'), False),
                          C.rendered(Fault('x')), C.rendered(Fault('x'), False), C.rendered(Nameless('x'))),
                         ('ValueError: plain', 'plain', f'Fault, {nr}', f'Fault, {nr}',
                          'an exception whose class and message could not be rendered'))

    def test_every_reason_the_tool_names_is_rendered_inside_the_guard_that_took_it(self):
        """The seven places that name a taken OSError's reason — the new folder's making and its opening, the new
        file's making, and undo's four: an identity not read, a making under way not looked for, a removal failing
        after its effect, a thing not removed —, given an OSError whose reason renders, and one whose reason raises
        when it is rendered: the first named by its reason, the second by the exception's class alone, nothing raised,
        exit 2. The helper itself on both, on an OSError with no reason, on one whose message raises and on an
        exception that is no OSError."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        nr = 'its message not rendered'
        eio = f'OSError: [Errno {errno.EIO}] injected'
        o_open, o_stat, o_unlink = os.open, os.stat, os.unlink
        for label, x, r, w in (
                ('renders', OSError(errno.EIO, 'a reason that renders'), 'a reason that renders',
                 f'OSError: [Errno {errno.EIO}] a reason that renders'),
                ('raises', OSError(errno.EIO, Fault('injected')), f'OSError, {nr}', f'OSError, {nr}')):
            def raising(*a, **kw):
                raise x

            def folder_open(path, flags, *a, **kw):
                if flags & os.O_DIRECTORY and kw.get('dir_fd') is not None:
                    raise x
                return o_open(path, flags, *a, **kw)

            def file_open(path, flags, *a, **kw):
                if flags & os.O_CREAT:
                    raise x
                return o_open(path, flags, *a, **kw)

            def stat(path, *a, **kw):
                if kw.get('dir_fd') is not None:
                    raise x
                return o_stat(path, *a, **kw)

            def unlink_after(path, *a, **kw):
                o_unlink(path, *a, **kw)
                raise x
            for name, kind, fault, patches, why in (
                    ('folder-made', 'table', None, {'mkdir': raising},
                     f'writing @ failed (OSError: the new folder cannot be made — {r}) — nothing it wrote is left'),
                    ('folder-opened', 'table', None, {'open': folder_open},
                     'writing @ failed (OSError: the new folder cannot be opened as the folder made — a link or another'
                     f' in its place ({r})) — left: @ — not opened as the folder the run made: not removed'),
                    ('file-made', 'a1', None, {'open': file_open},
                     f'writing @ failed (OSError: the new file cannot be made — {r}) — nothing it wrote is left'),
                    ('identity', 'a1', None, {'fstat': raising},
                     f'writing @ failed ({w}) — left: @ — made by the run, its identity not read ({r}): not removed'),
                    ('under-way', 'a1', None, {'open': file_open, 'stat': stat},
                     f'writing @ failed (OSError: the new file cannot be made — {r}) — left: @ — its making under way,'
                     f' not looked for: {r}'),
                    ('removed-after', 'a1', OSError(errno.EIO, 'injected'), {'unlink': unlink_after},
                     f'writing @ failed ({eio}) — nothing it wrote is left — @ — removed, its removal failing after its'
                     f' effect: {r}'),
                    ('not-removed', 'a1', OSError(errno.EIO, 'injected'), {'unlink': raising},
                     f'writing @ failed ({eio}) — left: @ — not removed: {r}')):
                out = self.path(f'{label}-{name}' + ('.json' if kind == 'a1' else ''))
                with contextlib.ExitStack() as st:
                    if fault is not None:
                        st.enter_context(mock.patch.object(C, 'put', mock.Mock(side_effect=fault)))
                    got, err = self.cli(fx, self.argv(fx, kind, out, ok), **patches)
                self.assertEqual((got, err), (2, 'STOP: ' + why.replace('@', out) + '\n'), (label, name))
        self.assertEqual((C.reason(OSError(errno.EIO, 'a reason')), C.reason(OSError(errno.EIO, Fault('x'))),
                          C.reason(OSError('no reason')), C.reason(FaultOS()), C.reason(ValueError('plain'))),
                         ('a reason', f'OSError, {nr}', 'no reason', f'FaultOS, {nr}', 'plain'))

    def test_a_partial_file_whose_removal_fails_is_named_and_every_descriptor_closed(self):
        """a1, its file's first write taking eleven bytes and its next failing with an ordinary EIO: its removal failing
        before its effect, and after it, with an OSError whose reason raises when it is rendered; and undo itself
        raising an exception that is no OSError: exit 2, one stop naming the writer's failure and the file as it is
        left — not removed, removed, or not all looked at —, the partial file where it is left, every descriptor the
        run took closed."""
        fx = Fixture(self.tmp)
        nr = 'its message not rendered'
        eio = f'OSError: [Errno {errno.EIO}] injected: the write failed'
        fds = '/proc/self/fd' if os.path.isdir('/proc/self/fd') else '/dev/fd'
        o_write, o_unlink = os.write, os.unlink
        writes = []

        def write(fd, data):
            if fd > 2:
                writes.append(fd)
                if len(writes) == 1:
                    return o_write(fd, bytes(data[:11]))
                raise OSError(errno.EIO, 'injected: the write failed')
            return o_write(fd, data)

        def before(path, *a, **kw):
            raise OSError(errno.EIO, Fault('injected'))

        def after(path, *a, **kw):
            o_unlink(path, *a, **kw)
            raise OSError(errno.EIO, Fault('injected'))

        def other(path, *a, **kw):
            raise RuntimeError('injected: undo itself raised')
        for name, unlink, why, size in (
                ('before', before, f'writing @ failed ({eio}) — left: @ — not removed: OSError, {nr}', 11),
                ('after', after, f'writing @ failed ({eio}) — nothing it wrote is left — @ — removed, its removal'
                                 f' failing after its effect: OSError, {nr}', None),
                ('other', other, f'writing @ failed ({eio}) — its undoing failed (RuntimeError: injected: undo itself'
                                 ' raised) — not all looked at, left as far as it knows: @', 11)):
            writes.clear()
            out = self.path(f'partial-{name}.json')
            held = len(os.listdir(fds))
            got, err = self.cli(fx, ['a1', self.tmp, fx.manifest, out], write=write, unlink=unlink)
            self.assertEqual((got, err, len(os.listdir(fds))), (2, 'STOP: ' + why.replace('@', out) + '\n', held), name)
            self.assertEqual(os.path.getsize(out) if os.path.lexists(out) else None, size, name)

    def test_a_stream_whose_own_flush_fails_is_taken_from_the_exits_flush(self):
        """The tool run as a process of its own, stdout — then stderr, stdout absent to ask a stop — an object over the
        real stream, its descriptor the real stream's, whose flush raises an ordinary exception every time: a1 and
        table — a synthetic build —: the process's exit 2, not 120, the stream taken from the interpreter's flush at
        exit; at stdout one stop naming the stream's failure and the outputs as left; the outputs written whole."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        for which in ('stdout', 'stderr'):
            for kind in ('a1', 'table'):
                out = self.path(f'flush-{which}-{kind}' + ('.json' if kind == 'a1' else ''))
                got, err = self.streams(fx, f'flush-fails {which}', self.argv(fx, kind, out, ok), stdout='pipe')
                left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                if kind == 'table' else [])
                self.assertEqual(got, 2, (which, kind, err))
                if which == 'stdout':
                    self.assertEqual(err, 'STOP: its own lines could not be written to stdout (RuntimeError: injected:'
                                     f' the flush raised) after writing {out} — {HELD}' + '; '.join(left) + '\n', kind)
                self.assertTrue(os.path.isfile(out) if kind == 'a1' else os.path.isdir(out), (which, kind))

    def test_a_stream_whose_own_flush_fails_over_its_closed_descriptor_is_taken_from_the_exits_flush(self):
        """The tool run as a process of its own, stdout — then stderr, stdout absent to ask a stop — an object over the
        real stream whose flush raises an ordinary exception every time, its write, fileno, close and closed state the
        real stream's, the real descriptor closed before the run, so that the null device's descriptor takes the
        stream's own number: form, a1, table and same — a synthetic build —: the process's exit 2, not 120, the
        stream taken from the interpreter's flush at exit; no descriptor left open by the run but the stream's own
        number, the null device's now, kept as the stream's; at stdout one stop naming the stream's failure — for a1
        and table the outputs as left, written whole —; at stderr the stop unsaid."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        head = 'STOP: its own lines could not be written to stdout (RuntimeError: injected: the flush raised)'
        for which in ('stdout', 'stderr'):
            for kind in ('form', 'a1', 'table', 'same'):
                out = self.path(f'flush-closed-{which}-{kind}' + ('.json' if kind == 'a1' else ''))
                marker = self.path(f'flush-closed-{which}-{kind}.fds')
                argv = {'form': ['form', ok], 'same': ['same', ok, ok]}.get(kind) or self.argv(fx, kind, out, ok)
                got, err = self.streams(fx, f'flush-closed {which} {marker}', argv, stdout='pipe')
                with open(marker, encoding='utf-8') as f:
                    self.assertEqual((got, f.read()), (2, '0'), (which, kind, err))
                if which == 'stderr':
                    self.assertEqual(err, '', kind)
                elif kind in ('a1', 'table'):
                    left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                    if kind == 'table' else [])
                    self.assertEqual(err, f'{head} after writing {out} — {HELD}' + '; '.join(left) + '\n', kind)
                    self.assertTrue(os.path.isfile(out) if kind == 'a1' else os.path.isdir(out), kind)
                else:
                    self.assertEqual(err, head + '\n', kind)

    def test_a_fileno_that_returns_no_int_is_no_descriptor_and_leaves_none_open(self):
        """The tool run as a process of its own, stdout — then stderr, stdout absent to ask a stop, its write failing —
        an object over the real stream whose fileno returns an object whose equality raises: a1 and table — a synthetic
        build —: exit 2, no descriptor left open by the run; at stdout one stop naming the stream's failure and the
        outputs as left; at stderr the stop unsaid; the outputs written whole."""
