    def test_a_fileno_past_the_c_ints_range_is_taken_in_and_leaves_none_open(self):
        """The tool run as a process of its own, stdout — then stderr, stdout absent to ask a stop, its write failing —
        an object over the real stream whose fileno returns an int past the C int's range — 2**31 and -2**31 - 1, the
        first past each end, which os.write and os.dup2 refuse with OverflowError —: a1 and table — a synthetic
        build —: exit 2, nothing out of quiet, no descriptor left open by the run; at stdout one stop naming the
        stream's failure and the outputs as left; at stderr the stop unsaid; the outputs written whole (M170)."""
        fx = Fixture(self.tmp)
        ok = self.dump('ok.json', fx.outputs())
        head = 'STOP: its own lines could not be written to stdout (OverflowError'
        for number in (2 ** 31, -2 ** 31 - 1):
            for which in ('stdout', 'stderr'):
                for kind in ('a1', 'table'):
                    tag = f'big{number}-{which}-{kind}'
                    out = self.path(tag + ('.json' if kind == 'a1' else ''))
                    marker = self.path(tag + '.fds')
                    got, err = self.streams(fx, f'big-fileno {which} {number} {marker}', self.argv(fx, kind, out, ok),
                                            stdout='pipe')
                    left = [out] + ([os.path.join(out, n) for n in ('table.tsv', 'cases.tsv', 'divergences.tsv')]
                                    if kind == 'table' else [])
                    with open(marker, encoding='utf-8') as f:
                        self.assertEqual((got, f.read()), (2, '0'), (number, which, kind, err))
                    if which == 'stdout':
                        self.assertTrue(err.startswith(head), err)
                        self.assertTrue(err.endswith(f' after writing {out} — {HELD}' + '; '.join(left) + '\n'), err)
                    else:
                        self.assertEqual(err, '', (number, kind))
                    self.assertTrue(os.path.isfile(out) if kind == 'a1' else os.path.isdir(out), (number, which, kind))

