    def test_the_decoders_and_the_json_parsers_words_are_rendered_inside_the_guard_that_took_them(self):
        """parse given bytes whose decoding raises a UnicodeDecodeError, and bytes whose parsing raises a ValueError,
        each one whose message raises when it is rendered: each named by its class alone, nothing raised; given the
        ordinary ones, the decoder's and the JSON parser's own words, unchanged."""
        nr = 'its message not rendered'

        class Undecodable(UnicodeDecodeError):
            def __str__(self):
                raise RuntimeError('injected: the message raised')

        class Unparsable(ValueError):
            def __str__(self):
                raise RuntimeError('injected: the message raised')

        class Raw(bytes):
            def decode(self, *args, **kwargs):
                raise Undecodable('utf-8', b'\xff', 0, 1, 'injected')

        self.assertEqual(C.parse(Raw(b'{}')), (None, [], f'the file is not UTF-8 (Undecodable, {nr})'))
        with mock.patch.object(C.json, 'loads', mock.Mock(side_effect=Unparsable('injected'))):
            self.assertEqual(C.parse(b'{}'), (None, [], f'the file does not parse as JSON (Unparsable, {nr})'))
        for raw, head, call in ((b'\xff{}', 'the file is not UTF-8', lambda: b'\xff{}'.decode('utf-8')),
                                (b'{"A1": ', 'the file does not parse as JSON', lambda: json.loads('{"A1": '))):
            with self.assertRaises(ValueError) as caught:
                call()
            self.assertEqual(C.parse(raw), (None, [], f'{head} ({caught.exception})'))

    def test_bytes_that_are_not_utf8_fail_every_output(self):
        fx = Fixture(self.tmp)
