        at = raw.index(b'"llfr": ') + len(b'"llfr": ')
        p = self.dump('latin.json', text=raw[:at] + b'\xff' + raw[at:])
        dev, n, nulls = C.form(*C.load(p))
        self.assertEqual((n, nulls), (0, 0))
        self.assertEqual(len(dev), 1)
        self.assertRegex(dev[0], r'^the file is not UTF-8 ')
        self.assertEqual(quiet(C.cmd_form, p, False)[0], 1)
        r, log = quiet(C.cmd_same, p, self.dump('ok.json', o))
        self.assertEqual(r, 1)
        self.assertIn('declared outputs: 535 · equal 0 · differing 535', log)
        log, t = self.table(fx, [('b', p)])
        self.assertEqual({(r[9], r[10]) for r in t['table.tsv'][2]}, {('FAIL', 'the file does not parse')})

